/* People account administration */
#page-directory { --people-ink: light-dark(#0b3025, var(--textPrimary)); --people-green: light-dark(#087454, var(--primaryGreen)); }
.people-intro { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; margin-bottom: 18px; padding: 2px 2px 0; }
.people-intro h2 { margin: 4px 0 3px; color: var(--people-ink); font-size: clamp(26px, 2.3vw, 36px); letter-spacing: -.035em; }
.people-intro p { margin: 0; color: var(--muted); font-size: 15px; }
.people-intro .eyebrow { color: var(--people-green); font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.people-primary-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 10px; }
.people-create-button { min-height: 46px; padding-inline: 20px; box-shadow: 0 12px 28px rgba(8,116,84,.22), inset 0 1px light-dark(rgba(255,255,255,.18), var(--highlight)); }

.people-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

button.people-stat {
  appearance: none;
  -webkit-appearance: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
  user-select: none;
  width: 100%;
}

.people-stat {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 100px;
  overflow: hidden;
  padding: 16px 20px;
  border: 1.5px solid light-dark(#d4e5dd, var(--border));
  border-radius: 20px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7fbf9, var(--surfaceAlt)) 100%);
  box-shadow:
    0 2px 6px rgba(6, 44, 32, 0.04),
    0 10px 24px -4px rgba(6, 44, 32, 0.07),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.25s cubic-bezier(0.16, 1, 0.3, 1),
              border-color 0.25s ease,
              background 0.25s ease;
}
.people-stat::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 3.5px;
  background: var(--stat-color, light-dark(#087454, var(--brand)));
  opacity: 0.7;
  transition: height 0.25s ease, opacity 0.25s ease, box-shadow 0.25s ease;
}
.people-stat::before {
  content: "";
  position: absolute;
  top: -35px;
  right: -35px;
  width: 105px;
  height: 105px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--brand))) 22%, transparent) 0%, transparent 70%);
  pointer-events: none;
  opacity: 0.5;
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.people-stat:hover {
  transform: translateY(-4px) scale(1.012);
  border-color: color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--successBorder))) 45%, light-dark(white, var(--border)));
  box-shadow:
    0 6px 16px rgba(6, 44, 32, 0.08),
    0 20px 38px -6px rgba(6, 44, 32, 0.14),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}
.people-stat:hover::before {
  opacity: 1;
  transform: scale(1.15);
}
.people-stat:hover::after {
  height: 4.5px;
  opacity: 1;
}
.people-stat:active {
  transform: translateY(-1px) scale(0.995);
  transition-duration: 0.08s;
}

/* 3D Active / Selected State for Stat Cards */
.people-stat.is-selected,
.people-stat.is-active {
  border-color: var(--stat-color, light-dark(#087454, var(--successBorder))) !important;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--brand))) 8%, light-dark(white, var(--surface))) 100%) !important;
  box-shadow:
    0 4px 12px color-mix(in srgb, var(--stat-color, #087454) 16%, transparent),
    0 16px 36px -6px color-mix(in srgb, var(--stat-color, #087454) 24%, transparent),
    inset 0 1.5px 0 light-dark(#ffffff, var(--highlight)) !important;
  transform: translateY(-3px) scale(1.01);
}
.people-stat.is-selected::after,
.people-stat.is-active::after {
  height: 5px !important;
  opacity: 1 !important;
  box-shadow: 0 -2px 10px var(--stat-color, #087454) !important;
}
.people-stat.is-selected::before,
.people-stat.is-active::before {
  opacity: 1 !important;
  transform: scale(1.25) !important;
}

.people-stat > .material-symbols-rounded {
  display: grid;
  flex: 0 0 48px;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--brand))) 14%, light-dark(white, var(--surface))) 100%);
  border: 1.5px solid color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--successBorder))) 26%, light-dark(white, var(--border)));
  color: var(--stat-color, light-dark(#087454, var(--primaryGreen)));
  font-size: 24px;
  box-shadow: 0 4px 10px color-mix(in srgb, var(--stat-color, #087454) 18%, transparent), inset 0 1px 1px light-dark(#ffffff, var(--highlight));
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.25s ease, background 0.25s ease;
}
.people-stat:hover > .material-symbols-rounded {
  transform: scale(1.08) rotate(3deg);
}
.people-stat.is-selected > .material-symbols-rounded,
.people-stat.is-active > .material-symbols-rounded {
  transform: scale(1.08) rotate(2deg);
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--brand))) 22%, light-dark(white, var(--surface))) 100%);
  border-color: color-mix(in srgb, var(--stat-color, light-dark(#087454, var(--successBorder))) 40%, light-dark(white, var(--border)));
  box-shadow: 0 6px 14px color-mix(in srgb, var(--stat-color, #087454) 30%, transparent), inset 0 1px 1px light-dark(#ffffff, var(--highlight));
}

.people-stat small, .people-stat strong { display: block; }
.people-stat small {
  color: light-dark(#4b6b5d, var(--textSecondary));
  font-family: 'Outfit', sans-serif;
  font-size: 11.5px;
  font-weight: 750;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.people-stat strong {
  margin: 2px 0 0;
  color: light-dark(#0c291e, var(--textPrimary));
  font-family: 'Outfit', sans-serif;
  font-size: 28px;
  font-weight: 850;
  line-height: 1.1;
  letter-spacing: -0.03em;
}
.people-stat--total { --stat-color: light-dark(#0b4a38, var(--primaryGreen)); }
.people-stat--barangay { --stat-color: light-dark(#087454, var(--primaryGreen)); }
.people-stat--lgu { --stat-color: light-dark(#2769aa, var(--info)); }
.people-stat--partner { --stat-color: light-dark(#995b00, var(--warning)); }
.people-stat--pending { --stat-color: light-dark(#995b00, var(--warning)); }
.people-summary-grid--barangay { grid-template-columns: repeat(2,minmax(0,1fr)); max-width: 580px; }

