  color: light-dark(#047857, var(--primaryGreen));
}

.people-filter-count {
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  display: inline-grid;
  place-items: center;
  border-radius: 9999px;
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#047857, var(--brand)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  font-size: 11px;
  font-weight: 800;
  box-shadow: 0 2px 6px rgba(5, 150, 105, 0.35);
}

/* Compact & User-Friendly 3D Filter Popover */
.people-filter-popover {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  z-index: 120;
  width: min(240px, calc(100vw - 32px));
  padding: 14px 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  border: 1px solid light-dark(rgba(16, 185, 129, 0.2), color-mix(in srgb, var(--successBorder) 20%, transparent));
  border-radius: 16px;
  background: light-dark(#ffffff, var(--surface));
  box-shadow: 0 16px 36px -6px rgba(6, 78, 59, 0.14), 0 6px 14px -3px rgba(6, 78, 59, 0.06), 0 0 0 1px rgba(16, 185, 129, 0.1);
  animation: peopleFilterSlide 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  transform-origin: top right;
}

/* Caret / Pointer pointing up to the Filter button */
.people-filter-popover::before {
  content: "";
  position: absolute;
  top: -6px;
  right: 24px;
  width: 10px;
  height: 10px;
  background: light-dark(#ffffff, var(--surface));
  border-left: 1px solid light-dark(rgba(16, 185, 129, 0.22), color-mix(in srgb, var(--successBorder) 22%, transparent));
  border-top: 1px solid light-dark(rgba(16, 185, 129, 0.22), color-mix(in srgb, var(--successBorder) 22%, transparent));
  transform: rotate(45deg);
  border-top-left-radius: 2px;
  z-index: 1;
}

@keyframes peopleFilterSlide {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.people-filter-popover[hidden] {
  display: none !important;
}

.people-filter-clear {
  display: none !important;
}

/* Fields & Selects */
.people-filter-grid {
