.activation-icon { width: 58px; height: 58px; display: grid; place-items: center; border-radius: 18px; background: linear-gradient(145deg,light-dark(#e4f5ed, var(--successSurface)),light-dark(#fff, var(--surface))); color: light-dark(#087454, var(--primaryGreen)); font-size: 29px; box-shadow: 0 11px 25px rgba(8,116,84,.12); }
.activation-heading p, .auth-card-heading > div > span { margin: 0 0 4px; color: light-dark(#0a8864, var(--primaryGreen)); font-size: 11px; font-weight: 800; letter-spacing: .13em; }
