.verification-reviewer-row input,.permission-check input { width: 20px; height: 20px; accent-color: var(--people-green); }
.verification-reviewer-manager { margin-top: 16px; }
.verification-reviewer-control { display: flex; align-items: center; gap: 10px; }
.verification-reviewer-control em { color: var(--muted); font-size: 11px; font-style: normal; font-weight: 700; }
.verification-document { display: grid; gap: 12px; }
.verification-document-link { justify-self: start; text-decoration: none; }
.verification-document-state { display: flex; min-height: 96px; align-items: center; justify-content: center; gap: 10px; border: 1px dashed light-dark(#c9ddd5, var(--border)); border-radius: 12px; background: light-dark(#f6fbf8, var(--surfaceAlt)); color: var(--muted); text-align: center; }
.verification-document-state p { margin: 0; }
.verification-document-state.is-loading > .material-symbols-rounded { color: var(--primary); animation: spin 1.1s linear infinite; }
.verification-document-state.is-error { flex-wrap: wrap; padding: 14px; border-color: light-dark(#edb8b4, var(--errorBorder)); background: light-dark(#fff7f5, var(--surfaceAlt)); color: light-dark(#a22929, var(--error)); }
.verification-document-state.is-error .text-button { flex-basis: 100%; justify-content: center; }
.verification-document-state.is-pdf { border-style: solid; background: light-dark(#fff8f6, var(--surfaceAlt)); color: light-dark(#9b332c, var(--error)); }
.verification-document-state.is-pdf > .material-symbols-rounded { font-size: 32px; }
.verification-review-instruction { display: flex; align-items: flex-start; gap: 10px; border-color: light-dark(#c9e5d9, var(--successBorder)); background: light-dark(#eff8f4, var(--surfaceAlt)); }
.verification-review-instruction > span { color: var(--people-green); }
.verification-review-instruction p { margin: 0; }
.verification-review-sections { display: grid; gap: 15px; }
.verification-review-section { padding: 16px; border: 1px solid light-dark(#dce9e3, var(--border)); border-radius: 15px; background: light-dark(#fbfdfc, var(--surface)); }
.verification-review-section > h3 { margin: 0 0 12px; color: var(--people-ink); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; }
.verification-review-sections > .verification-review-instruction { padding: 13px; border: 1px solid light-dark(#c9e5d9, var(--successBorder)); border-radius: 13px; }
.permission-check { display: flex; align-items: center; gap: 12px; padding: 12px; border: 1px solid var(--line); border-radius: 13px; background: light-dark(#f7fbf9, var(--surfaceAlt)); }
.permission-check strong,.permission-check small { display: block; }
.permission-check small { color: var(--muted); }
.verification-confirmation { display: grid; justify-items: center; gap: 12px; padding: 12px; text-align: center; }
.verification-confirmation > span { display: grid; place-items: center; width: 58px; height: 58px; border-radius: 18px; background: light-dark(#e4f4ec, var(--successSurface)); color: var(--people-green); font-size: 32px; }
.people-queue-page-surface table { min-width: 880px; }
.people-queue-page-surface tbody tr { transition: background .16s ease; }
.people-queue-page-surface tbody tr:hover { background: light-dark(#f3faf7, var(--hover)); }

.modal-card--people-wizard {
  width: min(680px, 94vw) !important;
  max-height: min(92vh, 760px) !important;
  display: flex !important;
  flex-direction: column !important;
  border-radius: 22px !important;
  border: 1.5px solid light-dark(#d4e5dc, var(--border)) !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  box-shadow:
    0 24px 60px -10px rgba(6, 44, 32, 0.28),
    0 10px 24px -4px rgba(6, 44, 32, 0.1),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight)) !important;
  overflow: hidden !important;
  animation: createAccountModalIn 0.24s cubic-bezier(0.16, 1, 0.3, 1) both !important;
}

@keyframes createAccountModalIn {
  0% {
    opacity: 0;
    transform: scale(0.97) translateY(10px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.modal-card--people-wizard .modal-header {
  min-height: 70px !important;
  padding: 18px 26px 14px !important;
  border-bottom: 1.5px solid light-dark(#e3eee8, var(--border)) !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  display: flex !important;
  align-items: flex-start !important;
  justify-content: space-between !important;
}

.modal-card--people-wizard .modal-header .icon-button {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: light-dark(#f4f8f6, var(--surfaceAlt));
  border: 1px solid light-dark(#d8e6df, var(--border));
  color: light-dark(#4b675c, var(--textSecondary));
  display: grid;
  place-items: center;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
}

.modal-card--people-wizard .modal-header .icon-button:hover {
  background: light-dark(#e8f3ee, var(--hover));
  color: light-dark(#0c3325, var(--textPrimary));
  transform: rotate(90deg);
}

.people-wizard-header-left {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.people-wizard-title {
  margin: 0;
  font-family: 'Outfit', sans-serif;
  font-size: 21px;
  font-weight: 800;
  color: light-dark(#0f2e23, var(--textPrimary));
  line-height: 1.25;
}

.people-wizard-subtitle {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
  color: light-dark(#5d786e, var(--textSecondary));
}

/* Success Header State */
.modal-card--people-wizard.is-success .modal-header {
  flex-direction: column !important;
  align-items: center !important;
  text-align: center !important;
  position: relative !important;
  padding: 24px 28px 8px !important;
  border-bottom: none !important;
}

.modal-card--people-wizard.is-success .modal-header .icon-button {
  position: absolute !important;
  top: 18px !important;
  right: 20px !important;
}

.account-created-circle {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  background: light-dark(#e7f7f0, var(--successSurface));
  border: 2.5px solid light-dark(#10b981, var(--successBorder));
  color: light-dark(#087454, var(--primaryGreen));
  display: grid;
  place-items: center;
  margin: 0 auto 12px;
  box-shadow: 0 6px 18px rgba(16, 185, 129, 0.22);
  animation: checkPop 0.3s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes checkPop {
  0% { transform: scale(0.6); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.account-created-circle .material-symbols-rounded {
  font-size: 34px;
  font-weight: 800;
}

.account-created-title {
  margin: 0;
  font-family: 'Outfit', sans-serif;
  font-size: 23px;
  font-weight: 850;
  color: light-dark(#0f2e23, var(--textPrimary));
  line-height: 1.2;
}

.account-created-subtitle {
  margin: 4px 0 0;
  font-size: 13.5px;
  font-weight: 500;
  color: light-dark(#577368, var(--textSecondary));
}

/* Body & Content */
.modal-card--people-wizard .modal-body {
  padding: 0 !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  overflow-y: auto !important;
  flex: 1 !important;
  scrollbar-width: thin;
  scrollbar-color: light-dark(#c4ded2, var(--textSecondary)) transparent;
}

.people-wizard-content {
  padding: 20px 26px 22px !important;
}

.people-wizard-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px 18px;
}

.wizard-3d-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.wizard-3d-field--full {
  grid-column: 1 / -1;
}

.wizard-inline-add {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 0;
  border: 0;
  background: transparent;
  color: light-dark(#087454, var(--primaryGreen));
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.wizard-inline-add .material-symbols-rounded { font-size: 17px; }
.wizard-inline-add:hover { color: light-dark(#064b38, var(--textPrimary)); text-decoration: underline; }
.wizard-inline-add:focus-visible { outline: 2px solid light-dark(#087454, var(--successBorder)); outline-offset: 3px; }

.wizard-inline-creator {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 16px;
  padding: 16px;
  border: 1px solid light-dark(#b9ddcd, var(--successBorder));
  border-radius: 14px;
  background: light-dark(#f2faf6, var(--surfaceAlt));
}

.wizard-inline-creator .button { grid-column: 1 / -1; justify-self: end; min-height: 42px; }

@media (max-width: 600px) {
  .wizard-inline-creator { grid-template-columns: 1fr; }
  .wizard-inline-creator .button { grid-column: auto; width: 100%; }
}

.wizard-field-label {
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 700;
  color: light-dark(#27473b, var(--textPrimary));
  letter-spacing: 0.01em;
}

.wizard-field-label .opt-tag {
  font-size: 11px;
  font-weight: 500;
  color: light-dark(#7b948b, var(--textSecondary));
  margin-left: 4px;
}

.wizard-3d-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
  height: 44px;
  border-radius: 12px;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#cfdfd7, var(--border));
  box-shadow:
    inset 0 1px 2px rgba(6, 44, 32, 0.03),
    0 1px 2px rgba(0, 0, 0, 0.02);
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
}

.wizard-3d-input-wrap:focus-within {
  border-color: light-dark(#087454, var(--successBorder));
  box-shadow:
    0 0 0 3px rgba(8, 116, 84, 0.16),
    inset 0 1px 2px rgba(0, 0, 0, 0.02);
}

.wizard-3d-input-wrap input,
.wizard-3d-input-wrap select {
  width: 100%;
  height: 100%;
  padding: 0 14px;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  font-family: 'Manrope', sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  color: light-dark(#123327, var(--textPrimary));
  border-radius: 12px;
}

.wizard-3d-input-wrap input::placeholder {
  color: light-dark(#92a79e, var(--textSecondary));
  font-weight: 450;
}

.wizard-3d-select-wrap select {
  appearance: none;
  -webkit-appearance: none;
  padding-right: 36px;
  cursor: pointer;
}

.wizard-3d-select-wrap select.wizard-select-placeholder { color: light-dark(#81998e, var(--textSecondary)); font-weight: 500; }

.wizard-select-caret {
  position: absolute;
  right: 12px;
  font-size: 20px;
  color: light-dark(#648175, var(--textSecondary));
  pointer-events: none;
  transition: transform 0.18s ease;
}

.wizard-3d-select-wrap:focus-within .wizard-select-caret {
  transform: rotate(180deg);
  color: light-dark(#087454, var(--primaryGreen));
}

.wizard-input-caption {
  font-size: 11.5px;
  color: light-dark(#617c72, var(--textSecondary));
  font-weight: 500;
  margin-top: 4px;
}

.wizard-auto-pw-note {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-radius: 10px;
  background: light-dark(#f4faf6, var(--surfaceAlt));
  border: 1px solid light-dark(#dbebe2, var(--border));
  color: light-dark(#446558, var(--textSecondary));
  font-size: 12px;
  font-weight: 600;
  margin-top: 2px;
}

.wizard-auto-pw-note .material-symbols-rounded {
  font-size: 16px;
  color: light-dark(#087454, var(--primaryGreen));
}

/* 3D Checkbox Card */
.wizard-checkbox-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 16px;
  border-radius: 12px;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d4e5dc, var(--border));
  box-shadow:
    0 1px 3px rgba(6, 44, 32, 0.04),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  cursor: pointer;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  user-select: none;
}

.wizard-checkbox-card:hover {
  border-color: light-dark(#bad6c8, var(--border));
  box-shadow: 0 4px 10px rgba(6, 44, 32, 0.07);
}

.wizard-checkbox-card input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.wizard-custom-checkbox {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  background: light-dark(#f4f8f5, var(--surfaceAlt));
  border: 1.5px solid light-dark(#b7d6c7, var(--border));
  color: transparent;
  transition: all 0.18s ease;
  flex-shrink: 0;
}

.wizard-custom-checkbox .material-symbols-rounded {
  font-size: 15px;
  font-weight: 800;
}

.wizard-checkbox-card input:checked ~ .wizard-custom-checkbox {
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 100%);
  border-color: light-dark(#047857, var(--successBorder));
  color: light-dark(#ffffff, var(--onAccent));
  box-shadow: 0 2px 6px rgba(16, 185, 129, 0.3);
}

.wizard-checkbox-info {
  display: flex;
  flex-direction: column;
}

.wizard-checkbox-info strong {
  font-size: 13px;
  font-weight: 750;
  color: light-dark(#123327, var(--textPrimary));
}

.wizard-checkbox-info small {
  font-size: 11.5px;
  color: light-dark(#657e74, var(--textSecondary));
}

/* Error States */
.wizard-3d-field.wizard-field--error .wizard-3d-input-wrap {
  border-color: light-dark(#dc2626, var(--errorBorder)) !important;
  background: light-dark(#fef2f2, var(--surfaceAlt)) !important;
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.14) !important;
}

.wizard-field-error {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 650;
  color: light-dark(#b91c1c, var(--error));
  margin-top: 4px;
}

.wizard-field-error .material-symbols-rounded {
  font-size: 14px;
}

/* 2-Column Info Grid (Used in Review & Success) */
.account-created-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 20px;
  padding: 16px 20px;
  border-radius: 14px;
  background: light-dark(#ffffff, var(--surface));
  border: 1px solid light-dark(#e1eee7, var(--border));
  box-shadow: 0 2px 6px rgba(6, 44, 32, 0.03);
}

.account-created-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.account-created-label {
  font-size: 11.5px;
  font-weight: 700;
  color: light-dark(#688378, var(--textSecondary));
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.account-created-val {
  font-size: 14px;
  font-weight: 650;
  color: light-dark(#123327, var(--textPrimary));
  overflow-wrap: anywhere;
}

/* Elevated Credential Box */
.account-created-cred-box {
  margin-top: 14px;
  padding: 14px 18px;
  border-radius: 14px;
  background: light-dark(#f4faf7, var(--surfaceAlt));
  border: 1.5px solid light-dark(#d0e4db, var(--border));
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.cred-box-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.cred-box-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.cred-box-label {
  font-size: 11px;
  font-weight: 700;
  color: light-dark(#6a857a, var(--textSecondary));
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.cred-box-val {
  font-size: 14.5px;
  font-weight: 750;
  color: light-dark(#0b3d2e, var(--textPrimary));
  overflow-wrap: anywhere;
}

.cred-pw-val {
  font-family: 'JetBrains Mono', monospace;
  letter-spacing: 0.08em;
  color: light-dark(#06553d, var(--primaryGreen));
}

.cred-copy-btn {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid light-dark(#c9ded4, var(--border));
  background: light-dark(#ffffff, var(--surface));
  color: light-dark(#087454, var(--primaryGreen));
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: 0 1px 3px rgba(6, 44, 32, 0.05);
  transition: all 0.16s ease;
  flex-shrink: 0;
}

.cred-copy-btn:hover {
  background: light-dark(#e8f5ef, var(--hover));
  border-color: light-dark(#a7d0be, var(--successBorder));
  transform: translateY(-1px);
}

.cred-copy-btn .material-symbols-rounded {
  font-size: 16px;
}

.cred-delivery-pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 9999px;
  background: light-dark(#e6f7ef, var(--successSurface));
  border: 1px solid light-dark(#b7e3d0, var(--successBorder));
  color: light-dark(#087454, var(--primaryGreen));
  font-size: 12px;
  font-weight: 750;
}

.cred-delivery-pill--sent {
  background: light-dark(#ecfdf5, var(--successSurface));
  border-color: light-dark(#a7f3d0, var(--successBorder));
  color: light-dark(#047857, var(--primaryGreen));
}

/* Bottom Note & 3 Buttons in Success Screen */
.account-created-export-note {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  font-size: 12.5px;
  font-weight: 600;
  color: light-dark(#557568, var(--textSecondary));
}

.account-created-export-note .material-symbols-rounded {
  font-size: 17px;
  color: light-dark(#087454, var(--primaryGreen));
}

.account-created-actions-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
}

.account-created-actions-row .button {
  width: 100% !important;
  justify-content: center !important;
  font-size: 12.5px !important;
  padding: 0 10px !important;
}

.button--full-done {
  width: 100% !important;
  justify-content: center !important;
  height: 46px !important;
  font-size: 15px !important;
  font-weight: 800 !important;
  border-radius: 12px !important;
}

/* Review Step Prompt */
.account-review-prompt {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
  padding: 12px 16px;
  border-radius: 12px;
  background: light-dark(#f0f8f4, var(--surfaceAlt));
  border: 1px solid light-dark(#cce5da, var(--successBorder));
  color: light-dark(#275242, var(--textPrimary));
  font-size: 12.5px;
  line-height: 1.4;
}

.account-review-prompt .material-symbols-rounded {
  font-size: 18px;
  color: light-dark(#087454, var(--primaryGreen));
  flex-shrink: 0;
}

/* Modal Actions */
.modal-card--people-wizard .modal-actions {
  min-height: 68px !important;
  padding: 14px 26px !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  border-top: 1.5px solid light-dark(#e3eee8, var(--border)) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  gap: 12px !important;
}

.button--3d-secondary {
  min-height: 42px;
  padding: 0 20px;
  border-radius: 11px;
  border: 1.5px solid light-dark(#cfdfd6, var(--border)) !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  color: light-dark(#3b5b4e, var(--textSecondary)) !important;
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 700;
  box-shadow: 0 1.5px 4px rgba(0, 0, 0, 0.04), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.button--3d-secondary:hover {
  background: light-dark(#f3f8f5, var(--hover)) !important;
  border-color: light-dark(#b9d3c5, var(--border)) !important;
  color: light-dark(#0f3528, var(--textPrimary)) !important;
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(6, 44, 32, 0.07);
}

.button--3d-create {
  min-height: 42px;
  padding: 0 22px;
  border-radius: 11px;
  background: light-dark(#087454, var(--brand)) !important;
  border: 1px solid light-dark(#065f46, var(--successBorder)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 800;
  letter-spacing: 0.01em;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  box-shadow:
    0 3px 12px rgba(8, 116, 84, 0.32),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.3), var(--highlight)) !important;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.button--3d-create:hover {
  background: light-dark(#09835f, var(--brandHover)) !important;
  transform: translateY(-1px);
  box-shadow:
    0 6px 18px rgba(8, 116, 84, 0.4),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.35), var(--highlight)) !important;
}

.button--3d-create:active {
  transform: translateY(0.5px);
  box-shadow: 0 2px 5px rgba(8, 116, 84, 0.2) !important;
}

@media (max-width: 640px) {
  .people-wizard-form {
    grid-template-columns: 1fr;
  }
  .account-created-grid {
    grid-template-columns: 1fr;
  }
  .account-created-actions-row {
    grid-template-columns: 1fr;
  }
  .people-wizard-content {
    padding: 16px 18px !important;
  }
  .modal-card--people-wizard .modal-actions {
    padding: 12px 18px !important;
    justify-content: stretch;
  }
  .modal-card--people-wizard .modal-actions .button {
    flex: 1;
    justify-content: center;
  }
}
