   ========================================================================== */

.modal-card--password-setup {
  width: min(540px, calc(100vw - 32px)) !important;
  max-height: calc(100dvh - 32px) !important;
  display: grid !important;
  grid-template-rows: auto minmax(0, 1fr) auto !important;
  border-radius: 24px !important;
  border: 1.5px solid light-dark(#d0e4d8, var(--border)) !important;
  background: linear-gradient(180deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7faf8, var(--surfaceAlt)) 100%) !important;
  box-shadow:
    0 28px 70px -12px rgba(6, 44, 32, 0.32),
    0 12px 28px -6px rgba(6, 44, 32, 0.14),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight)) !important;
  overflow: hidden !important;
  animation: setupModalIn 0.28s cubic-bezier(0.16, 1, 0.3, 1) both !important;
}

@keyframes setupModalIn {
  0% {
    opacity: 0;
    transform: scale(0.96) translateY(14px);
