.page-outlet > .page-section { width: 100%; min-width: 0; }
.page-section.active { display: block; animation: page-in 0.15s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes page-in { from { opacity: 0.92; transform: translateY(3px); } to { opacity: 1; transform: translateY(0); } }
.surface { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); }
.surface-header, .focus-header { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.surface-header { min-height: 76px; padding: 0 26px; border-bottom: 1px solid var(--line); }
.surface-header h2, .focus-header h2 { margin: 0; font-size: 22px; line-height: 1.25; }
.focus-header p { margin: 5px 0 0; color: var(--muted); font-size: 14px; }
.page-command-bar { margin-bottom: 22px; display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.page-command-bar--right { justify-content: flex-end; }
.invite-account-button { box-shadow: 0 10px 24px rgba(8,127,96,.22); }
.invite-account-button:hover { transform: translateY(-2px); box-shadow: 0 15px 30px rgba(8,127,96,.3); }
.invitation-note { margin: 18px 22px 4px; padding: 14px 16px; display: flex; align-items: center; gap: 12px; border: 1px solid light-dark(#b7d8cb, var(--border)); border-radius: 14px; background: var(--green-50); }
.invitation-note > span { width: 42px; height: 42px; display: grid; place-items: center; border-radius: 12px; background: var(--green-100); color: light-dark(var(--green-700), var(--primaryGreen)); }
.invitation-note strong, .invitation-note small { display: block; }
.invitation-note small { margin-top: 2px; color: var(--muted); font-size: 13px; }
.invite-intro { padding: 15px; display: grid; grid-template-columns: 48px 1fr; gap: 13px; align-items: center; border-radius: 14px; background: linear-gradient(135deg, var(--green-50), light-dark(#e5f6ef, var(--successSurface))); border: 1px solid light-dark(#b7d8cb, var(--border)); }
.invite-intro > span { width: 48px; height: 48px; display: grid; place-items: center; border-radius: 14px; background: light-dark(var(--green-700), var(--brand)); color: light-dark(white, var(--onAccent)); font-size: 26px; }
.invite-intro strong, .invite-intro small { display: block; }
.invite-intro small { color: var(--muted); }
.button { min-height: 48px; padding: 0 20px; display: inline-flex; align-items: center; justify-content: center; gap: 9px; border: 1px solid transparent; border-radius: 13px; font-size: 16px; font-weight: 700; }
.button--primary { background: light-dark(var(--green-700), var(--brand)); color: light-dark(white, var(--onAccent)); }
.button--primary:hover { background: light-dark(var(--green-800), var(--brandHover)); }
.button--secondary { border-color: light-dark(#b8cec4, var(--border)); background: light-dark(white, var(--surface)); color: light-dark(var(--green-800), var(--primaryGreen)); }
.button--secondary:hover { background: var(--green-50); }
.button--danger { background: light-dark(var(--danger), var(--errorSolid)); color: light-dark(white, var(--onAccent)); }
.button--danger:hover { background: light-dark(#a92828, var(--errorHover)); }
.button--block { width: 100%; }
.text-button { min-height: 44px; padding: 5px 10px; border: 0; background: transparent; color: light-dark(var(--green-700), var(--primaryGreen)); font-size: 14px; font-weight: 700; }
.text-button:hover { color: light-dark(var(--green-900), var(--primaryGreen)); text-decoration: underline; }

/* Dashboard */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}
.stat-card {
  min-height: auto;
  aspect-ratio: auto;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: light-dark(white, var(--surface));
  box-shadow: var(--shadow);
  text-align: left;
  color: var(--ink);
}
.stat-card .stat-icon { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 17px; font-size: 26px; }
.stat-card > span:nth-child(2) > span { display: block; color: var(--muted); font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; }
.stat-card strong { display: block; margin-top: 6px; font-size: 38px; line-height: 1; }
.stat-card .card-arrow { position: absolute; top: 22px; right: 22px; color: light-dark(#82968e, var(--textSecondary)); font-size: 20px; }
.stat-card--emergency .stat-icon { background: var(--danger-soft); color: light-dark(var(--danger), var(--error)); }
.stat-card--concern .stat-icon { background: var(--success-soft); color: light-dark(var(--success), var(--primaryGreen)); }
.stat-card--request .stat-icon { background: var(--warning-soft); color: var(--warning); }
.stat-card--review .stat-icon { background: var(--info-soft); color: var(--info); }
.dashboard-main-grid { margin-top: 24px; display: grid; grid-template-columns: minmax(0, 2.2fr) minmax(280px, .8fr); gap: 24px; }
.needs-action-panel { min-height: 440px; }
.action-list { padding: 8px 24px 20px; }
.action-row {
  min-height: 84px;
  padding: 12px 18px;
  display: grid;
  grid-template-columns: 46px minmax(0, 1.5fr) minmax(110px, 0.65fr) minmax(105px, 0.55fr) auto;
  gap: 16px;
  align-items: center;
  border: 1.5px solid transparent;
  border-radius: 16px;
  background: transparent;
  border-bottom: 1px solid light-dark(rgba(205, 226, 217, 0.6), color-mix(in srgb, var(--border) 60%, transparent));
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}
.action-row:last-child { border-bottom: 0; }
.action-row:hover {
  transform: translateX(4px) translateY(-1.5px);
  background: light-dark(#ffffff, var(--hover));
  border-color: light-dark(#d4e5dd, var(--border));
  box-shadow: 0 6px 18px rgba(6, 44, 32, 0.07);
}
.action-row > .material-symbols-rounded {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: linear-gradient(135deg, light-dark(#ecfdf5, var(--successSurface)) 0%, light-dark(#d1fae5, var(--successSurface)) 100%);
  border: 1.5px solid light-dark(#a7f3d0, var(--successBorder));
  border-top: 2px solid light-dark(#ffffff, var(--border));
  color: light-dark(#087454, var(--primaryGreen));
  font-size: 22px;
  box-shadow: 0 4px 10px rgba(16, 185, 129, 0.15), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  transition: transform 0.2s ease;
}
.action-row:hover > .material-symbols-rounded {
  transform: scale(1.08) rotate(3deg);
}
.action-row.urgent > .material-symbols-rounded {
  background: linear-gradient(135deg, light-dark(#fee2e2, var(--errorSurface)) 0%, light-dark(#fecaca, var(--errorSurface)) 100%);
  border-color: light-dark(#fca5a5, var(--errorBorder));
  color: light-dark(#b52d38, var(--error));
  box-shadow: 0 4px 10px rgba(220, 38, 38, 0.2), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}
.action-row strong {
  display: block;
  font-family: 'Outfit', sans-serif;
  font-size: 15px;
  font-weight: 800;
  color: light-dark(#0b3025, var(--textPrimary));
}
.action-row small {
  display: block;
  margin-top: 2px;
  color: light-dark(#5f746c, var(--textSecondary));
  font-size: 12px;
  font-weight: 600;
}
.action-row .action-location {
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 700;
  color: light-dark(#27453c, var(--textPrimary));
}
.action-row .wait-time {
  color: light-dark(#5f746c, var(--textSecondary));
  font-size: 12.5px;
  font-weight: 600;
}
.action-row .table-action {
  min-height: 36px;
  padding: 0 16px;
  border-radius: 10px;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d4e5dd, var(--border));
  color: light-dark(#065f46, var(--primaryGreen));
  font-family: 'Outfit', sans-serif;
  font-size: 12.5px;
  font-weight: 800;
  box-shadow: 0 2px 6px rgba(6, 44, 32, 0.04);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.action-row .table-action:hover {
  background: linear-gradient(135deg, light-dark(#087f60, var(--brandHover)) 0%, light-dark(#087f60, var(--brandHover)) 100%);
  border-color: light-dark(#10b981, var(--successBorder));
  color: light-dark(#ffffff, var(--onAccent));
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.35);
  transform: translateY(-1px);
}

/* Summary, queues, tables */
.compact-stats { display: flex; flex-wrap: wrap; gap: 14px; }
.mini-stat { min-width: 180px; min-height: 84px; padding: 13px 18px; display: flex; align-items: center; gap: 14px; border: 1px solid var(--line); border-radius: 17px; background: light-dark(white, var(--surface)); }
.mini-stat > .material-symbols-rounded { width: 46px; height: 46px; display: grid; place-items: center; border-radius: 14px; }
.mini-stat .danger { background: var(--danger-soft); color: light-dark(var(--danger), var(--error)); }
.mini-stat .warning { background: var(--warning-soft); color: var(--warning); }
.mini-stat .success { background: var(--success-soft); color: light-dark(var(--success), var(--primaryGreen)); }
.mini-stat .info { background: var(--info-soft); color: var(--info); }
.mini-stat span, .mini-stat strong { display: block; }
.mini-stat div > span { color: var(--muted); font-size: 14px; }
.mini-stat strong { margin-top: 2px; font-size: 25px; line-height: 1.15; }
.queue-surface { overflow: hidden; }
.segmented-tabs { display: flex; gap: 6px; padding: 18px 22px; overflow-x: auto; border-bottom: 1px solid var(--line); scrollbar-width: none; }
.segmented-tabs::-webkit-scrollbar { display: none; }
.segmented-tabs button { flex: 0 0 auto; min-height: 44px; padding: 0 17px; border: 1px solid transparent; border-radius: 12px; background: transparent; color: var(--muted); font-size: 16px; font-weight: 600; }
.segmented-tabs button:hover { background: var(--green-50); color: light-dark(var(--green-800), var(--primaryGreen)); }
.segmented-tabs button.active { background: var(--green-100); border-color: light-dark(#abd8c7, var(--successBorder)); color: light-dark(var(--green-800), var(--primaryGreen)); }
.segmented-tabs b { margin-left: 5px; }
.filter-bar, .filter-row, .library-tools, .report-toolbar { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; }
.filter-bar { padding: 18px 22px; background: light-dark(#fbfdfc, var(--surface)); border-bottom: 1px solid var(--line); }
.filter-bar label, .compact-filter { display: grid; gap: 6px; color: var(--muted); font-size: 13px; font-weight: 600; }
.filter-row { justify-content: flex-end; padding: 16px 22px 0; }
select, input, textarea { border: 1px solid light-dark(#c9d9d2, var(--border)); border-radius: 12px; background: light-dark(white, var(--surface)); color: var(--ink); }
select, input { min-height: 48px; padding: 0 14px; }
textarea { padding: 13px 14px; resize: vertical; }
select:hover, input:hover, textarea:hover { border-color: light-dark(#9bbcaf, var(--border)); }
select:focus, input:focus, textarea:focus { border-color: light-dark(var(--green-600), var(--successBorder)); box-shadow: 0 0 0 3px rgba(10,167,123,.13); outline: 0; }
.table-wrap { width: 100%; overflow-x: auto; }
table { width: 100%; border-collapse: collapse; }
th, td { padding: 18px 20px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; }
th { color: light-dark(#4f675e, var(--textSecondary)); background: light-dark(#fbfdfc, var(--surface)); font-size: 14px; font-weight: 700; }
td { color: var(--ink); font-size: 15px; }
tbody tr:hover { background: light-dark(#f8fcfa, var(--hover)); }
tbody tr:last-child td { border-bottom: 0; }
.cell-title, .cell-subtitle { display: block; }
.cell-title { font-weight: 700; }
.cell-subtitle { margin-top: 4px; color: var(--muted); font-size: 13px; }
.table-action { min-height: 42px; padding: 0 14px; border: 1px solid light-dark(#a8cdbf, var(--border)); border-radius: 11px; background: light-dark(white, var(--surface)); color: light-dark(var(--green-800), var(--primaryGreen)); font-size: 14px; font-weight: 700; }
.table-action:hover { background: var(--green-50); border-color: light-dark(var(--green-600), var(--successBorder)); }
.status-pill { display: inline-flex; align-items: center; min-height: 30px; padding: 4px 10px; border-radius: 999px; background: light-dark(#edf2f0, var(--surfaceAlt)); color: light-dark(#4f655c, var(--textSecondary)); font-size: 13px; font-weight: 700; white-space: nowrap; }
.status-pill.submitted, .status-pill.pending, .status-pill.pending_review, .status-pill.under_review, .status-pill.additional_document_required, .status-pill.warning, .status-pill.high { background: var(--warning-soft); color: light-dark(#855300, var(--warning)); }
.status-pill.acknowledged, .status-pill.assigned, .status-pill.processing, .status-pill.in_progress, .status-pill.scheduled { background: var(--info-soft); color: light-dark(#195a99, var(--info)); }
.status-pill.approved, .status-pill.resolved, .status-pill.completed, .status-pill.verified, .status-pill.active, .status-pill.published, .status-pill.paid { background: var(--success-soft); color: light-dark(#086c52, var(--primaryGreen)); }
.status-pill.rejected, .status-pill.suspended, .status-pill.urgent, .status-pill.critical, .status-pill.overdue { background: var(--danger-soft); color: light-dark(#ab2929, var(--error)); }
.status-pill.draft, .status-pill.archived, .status-pill.closed { background: light-dark(#edf2f0, var(--surfaceAlt)); color: light-dark(#4f655c, var(--textSecondary)); }
.status-pill.pending_delivery { background: var(--warning-soft); color: light-dark(#855300, var(--warning)); }
.status-pill.email_sent { background: var(--info-soft); color: light-dark(#195a99, var(--info)); }
.status-pill.accepted { background: var(--success-soft); color: light-dark(#086c52, var(--primaryGreen)); }
.status-pill.delivery_failed { background: var(--danger-soft); color: light-dark(#ab2929, var(--error)); }
.pagination { min-height: 64px; padding: 12px 20px; display: flex; justify-content: flex-end; align-items: center; gap: 8px; }
.pagination button { min-width: 42px; height: 42px; border: 1px solid var(--line); border-radius: 10px; background: light-dark(white, var(--surface)); color: var(--ink); }
.pagination button.active { background: light-dark(var(--green-700), var(--brand)); color: light-dark(white, var(--onAccent)); }
.concern-row { cursor: pointer; transition: background .16s ease, box-shadow .16s ease; }
.concern-row:hover { background: light-dark(#f3faf7, var(--hover)); }
.concern-row:focus-visible { outline: 3px solid light-dark(rgba(10, 167, 123, .24), color-mix(in srgb, var(--successBorder) 24%, transparent)); outline-offset: -3px; background: light-dark(#f3faf7, var(--surfaceAlt)); }
.concern-row td:first-child { position: relative; }
.concern-row:hover td:first-child::after, .concern-row:focus-visible td:first-child::after { content: ""; position: absolute; inset: 11px auto 11px 0; width: 3px; border-radius: 999px; background: light-dark(var(--green-600), var(--brandHover)); }
.concern-action-cell { width: 74px; text-align: right; }
.concern-kebab-button { width: 42px; height: 42px; display: inline-grid; place-items: center; border: 1px solid transparent; border-radius: 12px; background: transparent; color: light-dark(#506b61, var(--textSecondary)); transition: background .16s ease, border-color .16s ease, transform .16s ease; }
.concern-kebab-button:hover, .concern-kebab-button[aria-expanded="true"] { border-color: light-dark(#c8ddd4, var(--border)); background: light-dark(white, var(--hover)); color: light-dark(var(--green-800), var(--primaryGreen)); box-shadow: 0 7px 18px rgba(7, 71, 52, .1); }
.concern-kebab-button:active { transform: scale(.96); }
.concern-action-menu { position: fixed; z-index: 180; width: 290px; padding: 8px; border: 1px solid light-dark(#d4e3dc, var(--border)); border-radius: 16px; background: light-dark(rgba(255,255,255,.98), color-mix(in srgb, var(--surface) 98%, transparent)); box-shadow: 0 22px 60px rgba(5, 48, 35, .24); backdrop-filter: blur(18px); animation: concernMenuIn .16s ease both; }
.concern-action-menu button { width: 100%; min-height: 52px; padding: 9px 11px; display: grid; grid-template-columns: 35px 1fr; align-items: center; gap: 10px; border: 0; border-radius: 11px; background: transparent; color: var(--ink); text-align: left; }
.concern-action-menu button:hover, .concern-action-menu button:focus-visible { outline: 0; background: var(--green-50); color: light-dark(var(--green-800), var(--primaryGreen)); }
.concern-action-menu .material-symbols-rounded { color: light-dark(var(--green-700), var(--primaryGreen)); font-size: 21px; }
.concern-action-menu strong, .concern-action-menu small { display: block; }
.concern-action-menu strong { font-size: 13px; }
.concern-action-menu small { margin-top: 1px; color: var(--muted); font-size: 11px; }
@keyframes concernMenuIn { from { opacity: 0; transform: translateY(-5px) scale(.98); } to { opacity: 1; transform: none; } }
.empty-state { min-height: 150px; padding: 28px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; color: var(--muted); text-align: center; font-size: 14px; }
td.empty-state { display: table-cell; height: 160px; }
.empty-state .material-symbols-rounded { font-size: 34px; color: light-dark(#8ca39a, var(--textSecondary)); }

/* Focused forms and announcements */
.focus-panel { margin: 0 auto 24px; max-width: 980px; overflow: hidden; }
.focus-header { padding: 24px 28px; border-bottom: 1px solid var(--line); }
.simple-form { padding: 26px 28px; display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.field { display: grid; gap: 7px; min-width: 0; }
.field > span, fieldset > legend, .control-label { color: light-dark(#344f45, var(--textPrimary)); font-size: 15px; font-weight: 600; }
.field--full { grid-column: 1 / -1; }
fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.choice-group { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; }
.choice-group button { min-height: 50px; padding: 0 15px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 1px solid light-dark(#c5d8d0, var(--border)); border-radius: 12px; background: light-dark(white, var(--surface)); color: light-dark(#3f5d52, var(--textSecondary)); font-size: 16px; font-weight: 600; }
.choice-group button:hover { border-color: light-dark(var(--green-600), var(--successBorder)); }
.choice-group button.active { border-color: light-dark(var(--green-700), var(--successBorder)); background: var(--green-100); color: light-dark(var(--green-800), var(--primaryGreen)); box-shadow: inset 0 0 0 1px light-dark(var(--green-700), var(--primaryGreen)); }
.form-actions, .wizard-actions { display: flex; align-items: center; justify-content: flex-end; gap: 10px; }
.alert-history { margin-top: 22px; }
.emergency-intro { margin-bottom: 18px; padding: 22px 24px; display: grid; grid-template-columns: 58px minmax(0,1fr) auto; gap: 17px; align-items: center; border: 1px solid light-dark(#f0c4c4, var(--errorBorder)); border-radius: 22px; background: linear-gradient(135deg,light-dark(#fff8f7, var(--surfaceAlt)),light-dark(#fff, var(--surface)) 62%); box-shadow: 0 12px 30px rgba(153,38,38,.08); }
.emergency-intro > .material-symbols-rounded { width: 58px; height: 58px; display: grid; place-items: center; border-radius: 18px; background: var(--danger-soft); color: light-dark(var(--danger), var(--error)); font-size: 31px; }
.emergency-intro h2 { margin: 0; font-size: 24px; }
.emergency-intro p, .surface-header p { margin: 5px 0 0; color: var(--muted); font-size: 14px; }
.emergency-summary { margin-bottom: 18px; }
.emergency-summary .mini-stat { flex: 1; }
.emergency-alert-row { align-items: flex-start; }
.emergency-alert-icon { flex: 0 0 44px; width: 44px; height: 44px; display: grid; place-items: center; border-radius: 14px; background: var(--danger-soft); color: light-dark(var(--danger), var(--error)); }
.emergency-alert-copy { min-width: 0; flex: 1; }
.emergency-alert-copy p { margin: 6px 0; color: light-dark(#4f675e, var(--textSecondary)); font-size: 14px; line-height: 1.45; }
.emergency-alert-labels, .emergency-alert-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.emergency-alert-labels { margin-bottom: 5px; color: var(--muted); font-size: 13px; font-weight: 700; }
.emergency-alert-actions { justify-content: flex-end; }
.alert-behavior-note { padding: 14px 16px; display: grid; grid-template-columns: 42px 1fr; gap: 12px; align-items: center; border: 1px solid light-dark(#f0c4c4, var(--errorBorder)); border-radius: 15px; background: light-dark(#fff6f5, var(--surfaceAlt)); }
.alert-behavior-note > .material-symbols-rounded { width: 42px; height: 42px; display: grid; place-items: center; border-radius: 12px; background: var(--danger-soft); color: light-dark(var(--danger), var(--error)); }
.alert-behavior-note strong, .alert-behavior-note small { display: block; }
.alert-behavior-note small { margin-top: 3px; color: light-dark(#715b56, var(--textSecondary)); line-height: 1.4; }
.stack-list { padding: 14px 22px 22px; display: grid; gap: 10px; }
.list-card { min-height: 82px; padding: 14px 16px; display: flex; align-items: center; justify-content: space-between; gap: 15px; border: 1px solid var(--line); border-radius: 14px; background: light-dark(#fbfdfc, var(--surface)); }
.list-card strong, .list-card small { display: block; }
.list-card small { color: var(--muted); font-size: 13px; }
.announcement-summary { flex: 1; }
.announcement-composer { max-width: 1040px; }
.form-stepper { margin: 0; padding: 22px 28px; display: grid; grid-template-columns: repeat(3,1fr); list-style: none; border-bottom: 1px solid var(--line); }
.form-stepper li { position: relative; display: flex; align-items: center; justify-content: center; gap: 9px; color: light-dark(#72877f, var(--textSecondary)); font-size: 14px; font-weight: 600; }
.form-stepper li:not(:last-child)::after { content: ""; position: absolute; top: 50%; left: calc(50% + 55px); right: calc(-50% + 55px); height: 2px; background: var(--line); }
.form-stepper b { position: relative; z-index: 1; width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; background: light-dark(#e7efeb, var(--surfaceAlt)); color: light-dark(#567067, var(--textSecondary)); font-size: 14px; }
.form-stepper li.active, .form-stepper li.complete { color: light-dark(var(--green-800), var(--primaryGreen)); }
.form-stepper li.active b, .form-stepper li.complete b { background: light-dark(var(--green-700), var(--brand)); color: light-dark(white, var(--onAccent)); }
.form-stepper li.complete::after { background: light-dark(var(--green-600), var(--brand)); }
.form-step { min-height: 450px; padding: 28px; display: grid; align-content: start; gap: 20px; }
