.audience-summary { min-height: 88px; padding: 16px; display: flex; align-items: center; gap: 15px; border: 1px solid light-dark(#b7d8cb, var(--border)); border-radius: 15px; background: var(--green-50); }
.audience-summary > .material-symbols-rounded { width: 48px; height: 48px; display: grid; place-items: center; border-radius: 14px; background: var(--green-100); color: light-dark(var(--green-700), var(--primaryGreen)); font-size: 28px; }
