.barangay-checklist { max-height: 290px; overflow: auto; padding: 12px; display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 8px; }
.barangay-checklist label { min-height: 44px; padding: 8px 10px; display: flex; align-items: center; gap: 8px; border-radius: 10px; font-size: 14px; }
