.barangay-checklist input { min-height: auto; width: 18px; height: 18px; }
.switch-row { min-height: 76px; padding: 14px 16px; display: flex; align-items: center; justify-content: space-between; gap: 20px; border: 1px solid var(--line); border-radius: 14px; background: light-dark(#fbfdfc, var(--surface)); }
