}
.barangay-residents-entry > span:first-child { color: light-dark(#08795a, var(--brand)); font-size: 30px; }
.barangay-residents-entry > span:last-child { margin-left: auto; }
.barangay-residents-entry strong, .barangay-residents-entry small { display: block; }
.barangay-residents-entry small { margin-top: 3px; color: light-dark(#587267, var(--textSecondary)); }
.barangay-residents-report { padding: 22px; margin-bottom: 20px; color: light-dark(#123c30, var(--textPrimary)); }
.barangay-residents-heading { display: flex; align-items: flex-start; gap: 18px; margin-bottom: 22px; }
