.barangay-residents-toolbar { display: flex; align-items: end; gap: 14px; flex-wrap: wrap; margin-bottom: 16px; }
.barangay-residents-toolbar label { display: grid; gap: 5px; min-width: min(100%, 250px); font-size: 13px; font-weight: 650; }
.barangay-residents-toolbar input { width: 100%; padding: 10px 12px; border: 1px solid light-dark(#cde0d7, var(--border)); border-radius: 10px; background: light-dark(#fff, var(--surface)); color: inherit; }
