.barangay-residents-table-wrap { width: 100%; overflow-x: auto; margin-top: 15px; }
.barangay-residents-table-wrap table { width: 100%; min-width: 680px; border-collapse: collapse; }
#barangayResidentsResidents .barangay-residents-table-wrap table { min-width: 950px; }
.barangay-residents-table-wrap th, .barangay-residents-table-wrap td { padding: 12px; border-bottom: 1px solid light-dark(#e2ebe6, var(--border)); text-align: left; vertical-align: middle; }
.barangay-residents-table-wrap thead th { color: light-dark(#587267, var(--textSecondary)); font-size: 12px; text-transform: uppercase; }
.barangay-residents-table-wrap tbody th { font-weight: 650; }
#barangayResidentsBarangays tfoot { background: light-dark(#eaf5ef, var(--surfaceAlt)); }
#barangayResidentsBarangays tfoot th, #barangayResidentsBarangays tfoot td { border-top: 2px solid light-dark(#b8d7c8, var(--border)); font-weight: 750; }
.barangay-residents-table-wrap table.barangay-residents-status-table { min-width: 920px; }
