.barangay-residents-count--loggedIn { color: light-dark(#08795a, var(--brand)); font-weight: 650; }
.barangay-residents-count--total { font-weight: 650; }
.barangay-residents-note { margin: 12px 0 0; font-size: 13px; color: light-dark(#587267, var(--textSecondary)); }
.barangay-residents-error { padding: 12px; border-radius: 10px; background: light-dark(#fff4f1, var(--surfaceAlt)); color: light-dark(#a03022, var(--textPrimary)); }
.barangay-residents-pagination { display: flex; align-items: center; justify-content: flex-end; gap: 10px; margin-top: 16px; }
.barangay-residents-pagination span { margin-right: auto; }
@media (max-width: 600px) {
