  .barangay-residents-heading { flex-direction: column; }
  .barangay-residents-toolbar strong { margin-left: 0; width: 100%; }
}
.report-summary, .request-summary, .people-summary { margin-bottom: 22px; }
.analytics-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 22px; }
.chart-card, .analytics-wide { padding: 24px; }
.chart-card h2, .analytics-wide h2 { margin-bottom: 20px; font-size: 21px; }
.chart-container { position: relative; min-width: 0; min-height: 340px; overflow: hidden; }
.chart-container canvas { max-width: 100% !important; }
.analytics-wide { grid-column: 1 / -1; }
.metric-bars { display: grid; gap: 15px; }
.metric-bar header { margin-bottom: 6px; display: flex; justify-content: space-between; gap: 15px; font-size: 14px; }
.metric-bar > div { height: 10px; overflow: hidden; border-radius: 999px; background: light-dark(#e7efeb, var(--surfaceAlt)); }
.metric-bar i { display: block; height: 100%; border-radius: inherit; background: light-dark(var(--green-600), var(--brand)); }
.settings-layout { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 22px; }
.settings-card { padding: 26px; display: grid; align-content: start; gap: 19px; }
.settings-card legend { padding: 0 8px; font-size: 21px; color: var(--ink); font-weight: 700; }
.settings-card--broadcast { grid-template-columns: minmax(0, 1fr); }
.settings-card--broadcast .switch-row { width: 100%; }
.settings-advanced { grid-column: 1 / -1; padding: 20px 26px; }
.settings-advanced summary { cursor: pointer; color: var(--ink); font-size: 19px; font-weight: 750; }
.settings-advanced summary small { margin-left: 8px; color: var(--muted); font-size: 12px; font-weight: 650; }
.settings-advanced > p { margin: 12px 0 18px; color: var(--muted); font-size: 13px; }
.settings-advanced__fields { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.field-with-unit > span:last-child { display: grid; grid-template-columns: 1fr auto; align-items: center; border: 1px solid light-dark(#c9d9d2, var(--border)); border-radius: 12px; overflow: hidden; }
.field-with-unit > span:last-child:focus-within { border-color: light-dark(var(--green-600), var(--successBorder)); box-shadow: 0 0 0 3px rgba(10,167,123,.13); }
.field-with-unit input { border: 0; border-radius: 0; box-shadow: none; }
.field-with-unit em { padding: 0 14px; color: var(--muted); font-size: 13px; font-style: normal; }
.settings-savebar { grid-column: 1 / -1; min-height: 76px; padding: 13px 16px 13px 22px; display: flex; align-items: center; justify-content: space-between; gap: 16px; border: 1px solid light-dark(#a8cdbf, var(--border)); border-radius: 17px; background: light-dark(#ffffff, var(--surface)); box-shadow: var(--shadow); }
.settings-savebar span { color: var(--muted); font-size: 14px; }

/* Dynamic detail content */
.detail-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 14px; }
.detail-item { min-height: 78px; padding: 14px; border: 1px solid var(--line); border-radius: 13px; background: light-dark(#fbfdfc, var(--surface)); }
.detail-item.full { grid-column: 1 / -1; }
.detail-item label, .detail-item strong, .detail-item p { display: block; }
.detail-item label { margin-bottom: 5px; color: var(--muted); font-size: 13px; font-weight: 600; }
.detail-item strong { font-size: 15px; }
.detail-item p { margin: 0; white-space: pre-wrap; }
.case-form { margin-top: 20px; padding-top: 20px; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; border-top: 1px solid var(--line); }
.timeline { margin-top: 20px; display: grid; gap: 12px; }
.timeline-item { padding: 14px; display: grid; gap: 3px; border-left: 3px solid light-dark(var(--green-600), var(--successBorder)); background: var(--green-50); border-radius: 0 12px 12px 0; }
