.modal-card--timeline { width: min(680px, 100%); }

/* ==========================================================================
   3D Realistic "Refer to Another Office" Routing Modal
   ========================================================================== */
.modal-card--routing {
  width: min(560px, 100%) !important;
  border-radius: 20px !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  border: 1px solid light-dark(#cde0d7, var(--border)) !important;
  box-shadow:
    0 24px 60px -12px rgba(6, 44, 32, 0.28),
    0 8px 24px -4px rgba(6, 44, 32, 0.12),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight)) !important;
  overflow: hidden;
  animation: routingModalIn 0.24s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes routingModalIn {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.modal-card--routing .modal-header {
  padding: 18px 22px 14px !important;
  background: linear-gradient(135deg, light-dark(#f8fbf9, var(--surface)) 0%, light-dark(#edf7f2, var(--surfaceAlt)) 100%) !important;
  border-bottom: 1px solid light-dark(#dceae3, var(--border)) !important;
}

.modal-card--routing .modal-body {
  padding: 20px 22px !important;
  background: light-dark(#ffffff, var(--surface)) !important;
}

.modal-card--routing .modal-actions {
  padding: 14px 22px 18px !important;
  background: light-dark(#f8faf9, var(--surface)) !important;
  border-top: 1px solid light-dark(#e5ede8, var(--border)) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  gap: 10px !important;
}

.routing-review-workspace {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

/* 3D Case Snapshot Card */
.routing-case-snapshot {
  border-radius: 14px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f4f9f6, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#d3e7dd, var(--border));
  padding: 13px 16px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  box-shadow:
    0 2px 6px rgba(6, 44, 32, 0.04),
    0 8px 18px -4px rgba(6, 44, 32, 0.06),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.routing-snapshot-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.routing-cat-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 7px;
  background: light-dark(#eef8f3, var(--surfaceAlt));
  border: 1px solid light-dark(#c8e7d7, var(--successBorder));
  color: light-dark(#065f46, var(--primaryGreen));
  font: 800 11px 'Outfit', sans-serif;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.routing-cat-chip .material-symbols-rounded {
  font-size: 15px;
  color: light-dark(#047857, var(--primaryGreen));
}

.routing-ref-chip {
  font: 700 11px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  color: light-dark(#64748b, var(--textSecondary));
  letter-spacing: 0.03em;
  background: light-dark(#ffffff, var(--surface));
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid light-dark(#e2e8f0, var(--infoBorder));
}

.routing-concern-title {
  margin: 0;
  font: 800 15px 'Outfit', sans-serif;
  color: light-dark(#0b3d2c, var(--textPrimary));
  line-height: 1.3;
}

.routing-meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding-top: 9px;
  border-top: 1px solid light-dark(#e6f0eb, var(--border));
}

.routing-meta-cell {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.routing-meta-cell .material-symbols-rounded {
  font-size: 18px;
  color: light-dark(#087454, var(--primaryGreen));
  flex-shrink: 0;
}

.routing-meta-cell div {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
  min-width: 0;
}

.routing-meta-cell small {
  font: 700 8.5px 'Outfit', sans-serif;
  color: light-dark(#64748b, var(--textSecondary));
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.routing-meta-cell strong {
  font: 700 12.5px 'Manrope', sans-serif;
  color: light-dark(#0f172a, var(--textPrimary));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Smart Suggestion Banner */
.routing-smart-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 13px;
  border-radius: 10px;
  background: light-dark(#f0fdf4, var(--surfaceAlt));
