  color: light-dark(#166534, var(--primaryGreen));
}

.routing-smart-banner .material-symbols-rounded {
  font-size: 20px;
  color: light-dark(#087454, var(--primaryGreen));
  flex-shrink: 0;
}

.routing-smart-banner div {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.routing-smart-banner small {
  font: 700 8.5px 'Outfit', sans-serif;
  color: light-dark(#047857, var(--primaryGreen));
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.routing-smart-banner strong {
  font: 800 13px 'Outfit', sans-serif;
  color: light-dark(#064e3b, var(--primaryGreen));
}

/* Neutral Hint Banner */
.routing-hint-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 13px;
  border-radius: 10px;
  background: light-dark(#f8fafc, var(--surface));
  border: 1px solid light-dark(#e2e8f0, var(--infoBorder));
  color: light-dark(#475569, var(--textSecondary));
  font: 500 12px 'Manrope', sans-serif;
}

.routing-hint-banner .material-symbols-rounded {
  font-size: 18px;
  color: light-dark(#64748b, var(--textSecondary));
  flex-shrink: 0;
}

/* Form Field Groups */
.routing-field-group {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.routing-field-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.routing-field-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: 750 12.5px 'Outfit', sans-serif;
  color: light-dark(#1e293b, var(--textPrimary));
}

.routing-field-label .material-symbols-rounded {
  font-size: 17px;
  color: light-dark(#087454, var(--primaryGreen));
}

.routing-char-count {
  font: 600 10.5px 'Manrope', sans-serif;
  color: light-dark(#64748b, var(--textSecondary));
}

/* Select Input */
.routing-select-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.routing-select-input {
  width: 100%;
  min-height: 44px;
  padding: 0 38px 0 14px;
  border-radius: 10px;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d1e2da, var(--border));
  color: light-dark(#0f172a, var(--textPrimary));
  font: 600 13.5px 'Manrope', sans-serif;
  outline: none;
  cursor: pointer;
