  border-color: light-dark(#e2e8f0, var(--infoBorder));
}

.routing-select-arrow {
  position: absolute;
  right: 12px;
  pointer-events: none;
  font-size: 20px;
  color: light-dark(#64748b, var(--textSecondary));
}

/* Quick Shortcut Reason Chips */
.routing-quick-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 2px;
}

.routing-chip-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border-radius: 7px;
  background: light-dark(#f1f7f4, var(--surfaceAlt));
  border: 1px solid light-dark(#cfe0d8, var(--border));
  color: light-dark(#0b4a38, var(--textPrimary));
  font: 700 11px 'Outfit', sans-serif;
  cursor: pointer;
  transition: all 0.16s ease;
  user-select: none;
