.routing-chip-btn .material-symbols-rounded {
  font-size: 13px;
  color: light-dark(#047857, var(--primaryGreen));
}

.routing-chip-btn:hover {
  background: light-dark(#0b4a38, var(--brandStrong));
  border-color: light-dark(#06382a, var(--successBorder));
  color: light-dark(#ffffff, var(--onAccent));
  transform: translateY(-1px);
  box-shadow: 0 2px 6px rgba(11, 74, 56, 0.2);
