.routing-chip-btn:hover .material-symbols-rounded {
  color: light-dark(#a7f3d0, var(--primaryGreen));
}

.routing-chip-btn:active {
  transform: translateY(0);
}

/* Textarea Input */
.routing-textarea-input {
