}

.dashboard-approvals-empty .empty-3d-shield {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: linear-gradient(145deg, light-dark(#e8f5ee, var(--surfaceAlt)) 0%, light-dark(#d5ece0, var(--successSurface)) 100%);
  border: 1px solid light-dark(#bbf7d0, var(--successBorder));
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.14), inset 0 2px 0 light-dark(#ffffff, var(--highlight));
