  align-items: center;
  justify-content: center;
  color: light-dark(#087454, var(--primaryGreen));
}

.dashboard-approvals-empty .empty-3d-shield .material-symbols-rounded {
  font-size: 26px;
}

.dashboard-approvals-empty strong {
  font-family: 'Outfit', sans-serif;
  font-size: 15px;
  font-weight: 800;
  color: light-dark(#064e3b, var(--primaryGreen));
  letter-spacing: -0.01em;
}

/* 3D Realistic Empty States */
.empty-state {
  padding: 42px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 12px;
}

.empty-state .material-symbols-rounded {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  border-radius: 22px;
  background: linear-gradient(135deg, light-dark(#ecfdf5, var(--successSurface)) 0%, light-dark(#d1fae5, var(--successSurface)) 100%);
