}

.dashboard-verification-row:last-child {
  border-bottom: 0;
}

.dashboard-verification-row:hover {
  transform: translateX(4px);
  background: light-dark(#f0f7f4, var(--hover));
  box-shadow: 0 4px 14px rgba(7, 56, 42, 0.05);
}

.verification-avatar {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(135deg, light-dark(#dcfce7, var(--successSurface)), light-dark(#bbf7d0, var(--successSurface)));
