  justify-content: center;
  gap: 6px;
  border-radius: 12px;
  background: light-dark(#0b4a38, var(--brandStrong));
  border: 1px solid light-dark(#0b4a38, var(--successBorder));
  color: light-dark(#ffffff, var(--onAccent));
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 4px 10px rgba(11, 74, 56, 0.25);
