  box-shadow: 0 6px 16px rgba(16, 185, 129, 0.35);
}

.mini-stat { min-height: 78px; border-radius: 15px; background: light-dark(rgba(255,255,255,.95), color-mix(in srgb, var(--surface) 95%, transparent)); }
.mini-stat strong { font-size: 22px; }
.mini-stat div > span { font-size: 12px; font-weight: 650; }
.queue-surface, .library-surface { border-radius: 18px; }
.segmented-tabs { padding: 14px 18px; background: light-dark(rgba(248,251,249,.72), color-mix(in srgb, var(--surface) 72%, transparent)); }
.segmented-tabs button { min-height: 40px; border-radius: 10px; font-size: 14px; }
.segmented-tabs button.active { box-shadow: 0 5px 14px rgba(8, 103, 75, .08); }
.filter-bar, .library-tools { background: light-dark(rgba(249,252,250,.8), color-mix(in srgb, var(--surface) 80%, transparent)); }

select, input, textarea { border-color: light-dark(#d4e1db, var(--border)); background: light-dark(rgba(255,255,255,.96), color-mix(in srgb, var(--surface) 96%, transparent)); }
select, input { min-height: 46px; }
th { padding-block: 15px; background: light-dark(#f8fbf9, var(--surface)); font-size: 12px; text-transform: uppercase; letter-spacing: .045em; }
td { padding-block: 16px; font-size: 14px; }
tbody tr { transition: background .15s ease; }
.button { min-height: 46px; border-radius: 12px; font-size: 14px; transition: transform .16s ease, box-shadow .16s ease, background .16s ease; }
.button:not(:disabled):active { transform: translateY(1px) scale(.99); }
.button--primary { background: linear-gradient(135deg, light-dark(#087f60, var(--brand)), light-dark(#086148, var(--brandStrong))); box-shadow: 0 9px 19px rgba(8, 122, 89, .18); }
.button--primary:hover { background: linear-gradient(135deg, light-dark(#087a59, var(--brandHover)), light-dark(#074c39, var(--brandStrong))); box-shadow: 0 12px 24px rgba(8, 108, 78, .24); }
.button--secondary { background: light-dark(rgba(255,255,255,.94), color-mix(in srgb, var(--surface) 94%, transparent)); }
.table-action { background: light-dark(rgba(255,255,255,.96), color-mix(in srgb, var(--surface) 96%, transparent)); }
.status-pill { font-size: 11px; letter-spacing: .02em; }

.focus-panel { border-radius: 20px; }
.focus-header { padding: 20px 24px; }
.form-step { padding: 24px; }
.choice-group button, .upload-field, .audience-summary, .switch-row, .detail-item { border-radius: 13px; }
.modal-overlay { background: light-dark(rgba(4,31,23,.48), color-mix(in srgb, var(--brandStrong) 48%, transparent)); backdrop-filter: blur(9px); }
.modal-card {
  border: 1px solid light-dark(rgba(255,255,255,.64), color-mix(in srgb, var(--border) 64%, transparent));
  border-radius: 22px;
  background: light-dark(rgba(255,255,255,.96), color-mix(in srgb, var(--surface) 96%, transparent));
  box-shadow: 0 36px 100px rgba(4,37,27,.3);
}

.modal-card--alert { width: min(820px, 100%); }
.modal-card--alert .modal-header p { margin: 5px 0 0; color: var(--muted); }
.modal-card--alert .modal-header .icon-button { border: 1px solid light-dark(#d6e4de, var(--border)); background: light-dark(#f2f8f5, var(--surfaceAlt)); color: light-dark(#123b30, var(--textPrimary)); }
.modal-card--alert .simple-form { padding: 0; }
.modal-card--alert .barangay-checklist { max-height: 220px; overflow-y: auto; }
.password-guidance { display: flex; align-items: flex-start; gap: 10px; color: var(--muted); }
.password-guidance .material-symbols-rounded { color: var(--green-600, light-dark(#08765b, var(--primaryGreen))); font-size: 20px; }
.modal-lead { margin: 0 0 18px; color: var(--muted); }
.show-passwords { display: inline-flex; align-items: center; gap: 8px; width: fit-content; color: var(--muted); font-size: 13px; cursor: pointer; }
.show-passwords input { width: 18px; height: 18px; min-height: 0; }
.account-menu, .global-search-results {
  border-color: light-dark(rgba(192,215,204,.9), color-mix(in srgb, var(--border) 90%, transparent));
  background: light-dark(rgba(255,255,255,.96), color-mix(in srgb, var(--surface) 96%, transparent));
  backdrop-filter: blur(18px);
}

@media (max-width: 1280px) {
  .global-search { width: 230px; }
  .stat-card { min-height: 160px; }
}

@media (max-width: 1024px) {
  .sidebar {
    inset: 12px auto 12px 12px;
    width: min(310px, calc(100vw - 28px));
    border-radius: 24px;
    transform: translateX(calc(-100% - 20px));
  }
  .sidebar:is(.open, :focus-within) { width: min(310px, calc(100vw - 28px)); }
  .workspace { margin-left: 0; padding: 12px 20px 44px; }
  .sidebar:is(:hover, :focus-within, .open) ~ .workspace { margin-left: 0; filter: none; opacity: 1; }
  .sidebar.open ~ .workspace { filter: blur(1.5px); }
  .topbar { top: 10px; min-height: 78px; margin-bottom: 20px; }
