  .page-heading { min-width: 0; flex: 1; }
  .page-heading h1 { font-size: 23px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .stats-grid { grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 8px; }
