  .stat-value { font-size: 26px; }
  .stat-card .card-arrow { top: 18px; right: 18px; }
  .dashboard-analytics-grid { margin-top: 13px; gap: 13px; }
  .dashboard-chart-card { padding: 17px 16px 14px; }
  .dashboard-concern-map-card { padding: 17px 16px 14px; }
  .barangay-concern-insights { min-height: 0; }
  .concern-insight-chart { min-height: 200px; padding: 12px 10px; gap: 10px; }
  .barangay-analytics-header { align-items: stretch; flex-direction: column; gap: 10px; }
  .barangay-analytics-controls { justify-content: space-between; }
  .barangay-analytics-tabs button { min-width: 105px; }
  .barangay-analytics-legend { justify-content: flex-start; }
  .barangay-analytics-chart-container { min-height: 250px; }
  .analytics-card-header { min-height: 0; margin-bottom: 8px; }
  .analytics-card-header p { max-width: 250px; }
  .dashboard-activity-chart { min-height: 235px; }
  .dashboard-verification-panel { margin-top: 13px; }
  .dashboard-verification-header { align-items: center; }
  .dashboard-verification-header p { display: none; }
  .dashboard-verification-list { padding: 2px 12px 12px; }
  .dashboard-verification-row { grid-template-columns: 42px minmax(0,1fr) auto; gap: 10px; }
