  .verification-review { grid-column: 3; grid-row: 1 / span 2; }
  .dashboard-main-grid { gap: 13px; }
  .surface, .queue-surface, .library-surface { border-radius: 16px; }
  tbody tr { box-shadow: 0 6px 18px rgba(11,62,47,.055); }
}

