  border-radius: 10px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f5f9f7, var(--surfaceAlt)) 100%);
  border: 1px solid light-dark(rgba(205, 226, 217, 0.85), color-mix(in srgb, var(--border) 85%, transparent));
  font: 600 12.5px 'Outfit', sans-serif;
  color: light-dark(#2d4d42, var(--textPrimary));
  box-shadow: 0 2px 6px rgba(6, 44, 33, 0.03), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.alert-strip-item .strip-icon {
  font-size: 16px;
  color: light-dark(#087454, var(--primaryGreen));
}

.strip-item--highlight {
  background: linear-gradient(145deg, light-dark(#f0fdf4, var(--surfaceAlt)) 0%, light-dark(#e6f7f0, var(--successSurface)) 100%);
  border-color: light-dark(#a7f3d0, var(--successBorder));
  color: light-dark(#065f46, var(--primaryGreen));
}

.strip-item--highlight b {
  font-weight: 850;
  color: light-dark(#047857, var(--primaryGreen));
}

/* Card Footer */
#page-emergency .alert-card-footer {
  padding: 11px 22px;
  background: linear-gradient(180deg, light-dark(#fafcfb, var(--surface)) 0%, light-dark(#f4f8f6, var(--surfaceAlt)) 100%);
  border-top: 1px solid light-dark(rgba(218, 233, 226, 0.75), color-mix(in srgb, var(--border) 75%, transparent));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

#page-emergency .alert-source-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: 750 12px 'Outfit', sans-serif;
  color: light-dark(#4a685c, var(--textSecondary));
}

.source-check {
  font-size: 16px;
  color: light-dark(#087454, var(--primaryGreen));
}

/* 3D Action Buttons */
.details-3d-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 36px;
  height: 36px;
  padding: 0 14px;
  border-radius: 11px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f0f7f3, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#c2ded2, var(--border));
  color: light-dark(#065f46, var(--primaryGreen));
  font: 800 12px 'Outfit', sans-serif;
  letter-spacing: 0.02em;
  box-shadow: 
    0 2px 6px rgba(6, 95, 70, 0.08),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease, border-color 0.2s ease;
}

.details-3d-btn:hover {
  transform: translateY(-1.5px);
  border-color: light-dark(#059669, var(--successBorder));
  color: light-dark(#047857, var(--primaryGreen));
  box-shadow: 
    0 5px 14px rgba(6, 95, 70, 0.16),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.details-3d-btn .material-symbols-rounded {
  font-size: 16px;
}

.alert-end-button.end-3d-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 36px;
  height: 36px;
  padding: 0 14px;
  border-radius: 11px;
  background: linear-gradient(145deg, light-dark(#c93636, var(--errorSolid)) 0%, light-dark(#c93636, var(--errorSolid)) 100%) !important;
  border: 1px solid light-dark(#f87171, var(--errorBorder)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  font: 800 12px 'Outfit', sans-serif !important;
  letter-spacing: 0.02em;
  box-shadow: 0 3px 10px rgba(220, 38, 38, 0.25), inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.5), var(--highlight)) !important;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease !important;
}

.alert-end-button.end-3d-btn:hover {
  transform: translateY(-1.5px) !important;
  box-shadow: 0 6px 16px rgba(220, 38, 38, 0.4), inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.7), var(--highlight)) !important;
}

/* ==========================================================================
   UNIFIED 3D PUBLIC SAFETY COMMAND DECK (#page-emergency)
   ========================================================================== */
#page-emergency {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Command Deck Surface */
.emergency-command-deck {
  position: relative;
  background: linear-gradient(160deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f6faf8, var(--surfaceAlt)) 60%, light-dark(#eef6f2, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(rgba(255, 255, 255, 0.95), color-mix(in srgb, var(--border) 95%, transparent));
  border-radius: 24px;
  padding: 16px 24px;
  box-shadow: 
    0 12px 32px rgba(6, 44, 33, 0.06),
    0 2px 6px rgba(6, 44, 33, 0.03),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  display: flex;
  flex-direction: column;
}

/* Deck Header */
.emergency-deck-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.emergency-deck-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.emergency-deck-title {
  margin: 0;
  font: 850 25px 'Outfit', sans-serif;
  color: light-dark(#0b3025, var(--textPrimary));
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.emergency-live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 11px;
  border-radius: 999px;
  background: light-dark(rgba(5, 150, 105, 0.08), color-mix(in srgb, var(--brand) 8%, transparent));
  border: 1px solid light-dark(rgba(5, 150, 105, 0.25), color-mix(in srgb, var(--successBorder) 25%, transparent));
  color: light-dark(#047857, var(--primaryGreen));
  font: 800 11px 'Outfit', sans-serif;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  box-shadow: inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.8), var(--highlight));
}

.emergency-live-pill .live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: light-dark(#087f60, var(--brand));
  box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.6);
  animation: live-dot-pulse 2s infinite cubic-bezier(0.25, 0, 0, 1);
}

@keyframes live-dot-pulse {
  0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); }
  70% { box-shadow: 0 0 0 6px rgba(16, 185, 129, 0); }
  100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

/* 3D Dispatch Button */
.emergency-dispatch-3d-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 13px 24px;
  min-height: 50px;
  border-radius: 16px;
  background: linear-gradient(135deg, light-dark(#c93636, var(--errorSolid)) 0%, light-dark(#c93636, var(--errorSolid)) 55%, light-dark(#b91c1c, var(--errorSolid)) 100%);
  border: 1px solid light-dark(rgba(255, 255, 255, 0.35), color-mix(in srgb, var(--border) 35%, transparent));
  border-bottom: 3px solid light-dark(#991b1b, var(--errorBorder));
  color: light-dark(#ffffff, var(--onAccent));
  font: 800 14px 'Outfit', 'Manrope', sans-serif;
  letter-spacing: 0.02em;
  box-shadow: 
    0 10px 24px rgba(220, 38, 38, 0.38),
    0 2px 4px rgba(0, 0, 0, 0.12),
    inset 0 1px 1px light-dark(rgba(255, 255, 255, 0.7), var(--highlight));
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1), filter 0.2s ease;
  flex-shrink: 0;
}

.emergency-dispatch-3d-btn:hover {
  transform: translateY(-2px);
  box-shadow: 
    0 14px 30px rgba(220, 38, 38, 0.48),
    0 4px 8px rgba(0, 0, 0, 0.14),
    inset 0 1px 1px light-dark(rgba(255, 255, 255, 0.85), var(--highlight));
  filter: brightness(1.05);
}

.emergency-dispatch-3d-btn:active {
  transform: translateY(2px);
  border-bottom-width: 1px;
  box-shadow: 0 4px 12px rgba(220, 38, 38, 0.3);
}

.emergency-dispatch-3d-btn .siren-icon {
  font-size: 22px;
  animation: siren-wiggle 2.4s infinite ease-in-out;
}

@keyframes siren-wiggle {
  0%, 100% { transform: rotate(0); }
  20% { transform: rotate(-12deg); }
  40% { transform: rotate(12deg); }
  60% { transform: rotate(-6deg); }
  80% { transform: rotate(6deg); }
}

/* 3D Status Tokens Deck */
.emergency-deck-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

@media (max-width: 860px) {
  .emergency-deck-metrics {
    grid-template-columns: 1fr;
  }
}

.metric-token-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  min-height: 74px;
  border-radius: 20px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7fbf9, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#d4e5dd, var(--border));
  box-shadow: 
    0 2px 6px rgba(6, 44, 32, 0.04),
    0 10px 24px -4px rgba(6, 44, 32, 0.07),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.2s ease;
}

.metric-token-card:hover {
  transform: translateY(-3px);
  border-color: light-dark(#b7ded0, var(--successBorder));
  box-shadow: 
    0 6px 14px rgba(6, 44, 32, 0.06),
    0 18px 36px -6px rgba(6, 44, 32, 0.14),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.metric-gem {
  width: 44px;
  height: 44px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  transition: transform 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.metric-token-card:hover .metric-gem {
  transform: scale(1.06);
}

.metric-gem .material-symbols-rounded {
  font-size: 24px;
}

/* Gem variants */
.gem-shield {
  background: linear-gradient(145deg, light-dark(#e6f7f0, var(--successSurface)) 0%, light-dark(#d1fae5, var(--successSurface)) 100%);
  border: 1px solid light-dark(#a7f3d0, var(--successBorder));
  color: light-dark(#087454, var(--primaryGreen));
  box-shadow: 0 3px 8px rgba(5, 150, 105, 0.15), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.gem-active {
  background: linear-gradient(145deg, light-dark(#fef2f2, var(--surfaceAlt)) 0%, light-dark(#fee2e2, var(--errorSurface)) 100%);
  border: 1px solid light-dark(#fca5a5, var(--errorBorder));
  color: light-dark(#b52d38, var(--error));
  box-shadow: 0 3px 8px rgba(220, 38, 38, 0.15), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.gem-resolved {
  background: linear-gradient(145deg, light-dark(#eff6ff, var(--infoSurface)) 0%, light-dark(#dbeafe, var(--infoSurface)) 100%);
  border: 1px solid light-dark(#bfdbfe, var(--infoBorder));
  color: light-dark(#2563eb, var(--info));
  box-shadow: 0 3px 8px rgba(37, 99, 235, 0.15), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.metric-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.metric-label {
  font: 750 11px 'Outfit', sans-serif;
  color: light-dark(#697f76, var(--textSecondary));
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.metric-value {
  font: 850 18px 'Outfit', sans-serif;
  color: light-dark(#0b3025, var(--textPrimary));
  margin-top: 1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.metric-value--number {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.metric-token--active .metric-value--number {
  color: light-dark(#b52d38, var(--error));
}

.metric-token--resolved .metric-value--number {
  color: light-dark(#2563eb, var(--info));
}

/* Dynamic State on Clear Card */
#clearEmergencyCard.has-alerts {
  background: linear-gradient(145deg, light-dark(#fff5f5, var(--surfaceAlt)) 0%, light-dark(#fee2e2, var(--errorSurface)) 100%);
  border-color: light-dark(#fca5a5, var(--errorBorder));
  box-shadow: 0 6px 20px rgba(220, 38, 38, 0.15);
}

#clearEmergencyCard.has-alerts .metric-gem {
  background: light-dark(#c93636, var(--errorSolid));
  color: light-dark(#ffffff, var(--onAccent));
  border-color: light-dark(#dc2626, var(--errorBorder));
  box-shadow: 0 4px 14px rgba(220, 38, 38, 0.35);
}

#clearEmergencyCard.has-alerts .metric-value {
  color: light-dark(#b91c1c, var(--error));
}

/* Feed Surface */
.emergency-feed-surface {
  background: light-dark(#ffffff, var(--surface));
  border: 1px solid light-dark(rgba(205, 226, 217, 0.75), color-mix(in srgb, var(--border) 75%, transparent));
  border-radius: 22px;
  box-shadow: 0 8px 26px rgba(6, 44, 33, 0.04);
  overflow: hidden;
}

.emergency-feed-toolbar {
  padding: 14px 18px;
  background: linear-gradient(180deg, light-dark(#fcfdfd, var(--surface)) 0%, light-dark(#f6faf8, var(--surfaceAlt)) 100%);
  border-bottom: 1px solid light-dark(rgba(205, 226, 217, 0.6), color-mix(in srgb, var(--border) 60%, transparent));
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.emergency-segmented-tabs {
  display: inline-flex;
  padding: 5px;
  border-radius: 14px;
  background: light-dark(#e9f2ee, var(--surfaceAlt));
  border: 1px solid light-dark(rgba(195, 219, 209, 0.7), color-mix(in srgb, var(--border) 70%, transparent));
  box-shadow: inset 0 2px 4px rgba(6, 44, 33, 0.05);
  gap: 4px;
}

.emergency-segmented-tabs button {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  min-height: 38px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: light-dark(#557267, var(--textSecondary));
  font: 750 13px 'Outfit', sans-serif;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.emergency-segmented-tabs button:hover {
  color: light-dark(#0b3025, var(--textPrimary));
}

.emergency-segmented-tabs button.active {
  background: light-dark(#ffffff, var(--surface));
  color: light-dark(#08664f, var(--primaryGreen));
  box-shadow: 
    0 3px 10px rgba(6, 44, 33, 0.08),
    0 1px 2px rgba(6, 44, 33, 0.04);
}

.emergency-segmented-tabs button .material-symbols-rounded {
  font-size: 18px;
}

.tab-count-pill {
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: light-dark(#08765b, var(--brand));
  color: light-dark(#ffffff, var(--onAccent));
  font: 850 11px 'Outfit', sans-serif;
  display: inline-grid;
  place-items: center;
}

.emergency-segmented-tabs button.active .tab-count-pill {
  background: light-dark(#c93636, var(--errorSolid));
}

/* 3D Empty State with Soft Radar Ripple */
.emergency-3d-empty {
  padding: 64px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.empty-3d-beacon {
  position: relative;
  width: 88px;
  height: 88px;
  display: grid;
  place-items: center;
  margin-bottom: 20px;
}

.beacon-pulse-ring {
  position: absolute;
  inset: -12px;
  border-radius: 50%;
  pointer-events: none;
}

.empty-3d-beacon.is-clear .beacon-pulse-ring {
  border: 1.5px solid light-dark(rgba(16, 185, 129, 0.35), color-mix(in srgb, var(--successBorder) 35%, transparent));
  animation: radar-beacon-ripple 2.8s infinite cubic-bezier(0.215, 0.61, 0.355, 1);
}

.empty-3d-beacon.is-clear .ring-2 {
  animation-delay: 1.4s;
}

.empty-3d-beacon.is-archive .beacon-pulse-ring {
  border: 1.5px solid light-dark(rgba(99, 102, 241, 0.3), color-mix(in srgb, var(--infoBorder) 30%, transparent));
}

@keyframes radar-beacon-ripple {
  0% { transform: scale(0.65); opacity: 0.9; }
  100% { transform: scale(1.45); opacity: 0; }
}

.beacon-gem {
  position: relative;
  width: 64px;
  height: 64px;
  border-radius: 20px;
  display: grid;
  place-items: center;
  z-index: 2;
  box-shadow: 0 10px 24px rgba(7, 70, 53, 0.12), inset 0 1px 1px light-dark(rgba(255, 255, 255, 0.9), var(--highlight));
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.empty-3d-beacon.is-clear .beacon-gem {
  background: linear-gradient(145deg, light-dark(#e6f7f0, var(--successSurface)) 0%, light-dark(#d1fae5, var(--successSurface)) 100%);
  border: 1.5px solid light-dark(#a7f3d0, var(--successBorder));
  color: light-dark(#087454, var(--primaryGreen));
}

.empty-3d-beacon.is-archive .beacon-gem {
  background: linear-gradient(145deg, light-dark(#eff6ff, var(--infoSurface)) 0%, light-dark(#e0e7ff, var(--infoSurface)) 100%);
  border: 1.5px solid light-dark(#c7d2fe, var(--infoBorder));
  color: light-dark(#4338ca, var(--info));
}

.beacon-gem .material-symbols-rounded {
  font-size: 32px;
}

.emergency-3d-empty h3 {
  margin: 0;
  font: 850 20px 'Outfit', sans-serif;
  color: light-dark(#0b3025, var(--textPrimary));
  letter-spacing: -0.02em;
}

.emergency-3d-empty p {
  margin: 6px 0 0;
  font: 550 14px 'Manrope', sans-serif;
  color: light-dark(#5f746c, var(--textSecondary));
}

/* CENTERED 3D EMERGENCY ALERT MODAL DIALOG */
#emergencyAlertModal {
  padding: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: light-dark(rgba(3, 30, 22, 0.6), color-mix(in srgb, var(--brandStrong) 60%, transparent));
  backdrop-filter: blur(8px);
  z-index: 1000;
}

#emergencyAlertModal .modal-card--alert {
  width: min(840px, calc(100vw - 32px));
  max-height: min(92vh, 880px);
  height: auto;
  display: flex;
  flex-direction: column;
  border-radius: 26px;
  background: linear-gradient(175deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7faf8, var(--surfaceAlt)) 100%);
  border: 1px solid light-dark(rgba(255, 255, 255, 0.95), color-mix(in srgb, var(--border) 95%, transparent));
  box-shadow: 0 28px 75px rgba(3, 32, 23, 0.32), 0 4px 16px rgba(0, 0, 0, 0.08), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  overflow: hidden;
  animation: emergency-modal-pop 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes emergency-modal-pop {
  from { transform: scale(0.94) translateY(14px); opacity: 0; }
  to { transform: scale(1) translateY(0); opacity: 1; }
}

#emergencyAlertModal .modal-header {
  padding: 22px 28px 16px;
  border-bottom: 1px solid light-dark(rgba(205, 226, 217, 0.65), color-mix(in srgb, var(--border) 65%, transparent));
  background: light-dark(#ffffff, var(--surface));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

#emergencyAlertModal .modal-header .eyebrow {
  color: light-dark(#b52d38, var(--error));
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#emergencyAlertModal .modal-header h2 {
  margin: 3px 0 0;
  color: light-dark(#0b3025, var(--textPrimary));
  font: 850 22px 'Outfit', sans-serif;
  letter-spacing: -0.02em;
}

#emergencyAlertModal .modal-header p {
  margin: 4px 0 0;
  color: light-dark(#697f76, var(--textSecondary));
  font: 550 12px 'Manrope', sans-serif;
}

#emergencyAlertModal .modal-header .icon-button {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  border: 1px solid light-dark(rgba(205, 226, 217, 0.8), color-mix(in srgb, var(--border) 80%, transparent));
  background: light-dark(#f4f8f6, var(--surfaceAlt));
  color: light-dark(#335549, var(--textPrimary));
  transition: all 0.2s ease;
}

#emergencyAlertModal .modal-header .icon-button:hover {
  background: light-dark(#fee2e2, var(--errorSurface));
  border-color: light-dark(#fca5a5, var(--errorBorder));
  color: light-dark(#b52d38, var(--error));
}

/* Stepper */
.alert-form-stepper {
  padding: 12px 32px 14px;
  display: flex;
  align-items: center;
  background: light-dark(#ffffff, var(--surface));
  border-bottom: 1px solid light-dark(rgba(205, 226, 217, 0.65), color-mix(in srgb, var(--border) 65%, transparent));
}

.alert-form-stepper > span {
  flex: 0 0 110px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: light-dark(#5f746c, var(--textSecondary));
  font: 700 11px 'Manrope', sans-serif;
}

.alert-form-stepper > span b {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border: 1.5px solid light-dark(#cfddd7, var(--border));
  border-radius: 50%;
  background: light-dark(#f7faf8, var(--surfaceAlt));
  font: 800 11px 'Outfit', sans-serif;
  color: light-dark(#5f746c, var(--textSecondary));
  transition: all 0.2s ease;
}

.alert-form-stepper > span em {
  font-style: normal;
  white-space: nowrap;
}

.alert-form-stepper > span.active {
  color: light-dark(#0b3025, var(--textPrimary));
  font-weight: 800;
}

.alert-form-stepper > span.active b {
  border-color: light-dark(#dc2626, var(--errorBorder));
  background: light-dark(#c93636, var(--errorSolid));
  color: light-dark(#ffffff, var(--onAccent));
