}

#page-concerns .concern-browser { position: relative; height: 100%; padding: 18px; isolation: isolate; }
#page-concerns .concern-browser::before {
  content: "";
  position: absolute;
  z-index: -1;
  left: 50%;
  top: 58%;
  width: clamp(260px, 34vw, 520px);
  aspect-ratio: 1;
  background: url("assets/barili-logoo.png") center / contain no-repeat;
  opacity: .035;
  filter: grayscale(1);
  transform: translate(-50%, -50%);
  pointer-events: none;
}
#page-concerns .concern-detail-pane { display: none; height: 100%; }
#page-concerns.show-detail .concern-browser { display: none; }
#page-concerns.show-detail .concern-detail-pane { display: block; }

.concern-browser-header {
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.concern-browser-heading { display: flex; align-items: center; gap: 12px; min-width: 0; }
.concern-browser-heading__icon { display: inline-grid; width: 38px; height: 38px; flex: 0 0 38px; place-items: center; border-radius: 10px; background: light-dark(#e4f6ee, var(--successSurface)); color: light-dark(#087458, var(--primaryGreen)); font-size: 22px; }
.concern-browser-actions { display: flex; align-items: center; justify-content: flex-end; flex-wrap: wrap; gap: 8px; margin-left: auto; }
.concern-filter-anchor { position: relative; }
.concern-filter-button { min-height: 42px; padding: 0 14px; border-radius: 12px; font-size: 13px; font-weight: 750; }
.concern-filter-button.has-filters { border-color: light-dark(#0a8767, var(--successBorder)); background: light-dark(#e8f7f0, var(--surfaceAlt)); color: light-dark(#075c44, var(--primaryGreen)); }
.concern-filter-count { min-width: 20px; height: 20px; padding: 0 5px; display: inline-grid; place-items: center; border-radius: 50%; background: light-dark(#087458, var(--brand)); color: light-dark(#fff, var(--onAccent)); font-size: 11px; }
.concern-filter-count[hidden], .concern-filter-popover[hidden] { display: none; }
.concern-filter-popover {
  position: absolute;
  z-index: 50;
  top: calc(100% + 8px);
  right: 0;
  width: min(340px, calc(100vw - 32px));
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  border: 1px solid light-dark(#d1fae5, var(--successBorder));
  border-radius: 16px;
  background: light-dark(#ffffff, var(--surface));
  box-shadow: 0 20px 48px -6px rgba(6, 78, 59, 0.16), 0 0 0 1px rgba(6, 78, 59, 0.06);
  animation: concernFilterPop 0.18s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes concernFilterPop {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.concern-filter-popover__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid light-dark(#f1f5f9, var(--border));
}

