/* 3D Tactile Status Tabs */
.concern-status-tabs {
  min-height: 48px;
  padding: 6px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  border: 1px solid light-dark(#cde0d7, var(--border));
  border-radius: 14px;
  background: light-dark(#ffffff, var(--surface));
  box-shadow: 0 2px 8px rgba(6, 44, 32, 0.04), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  margin-bottom: 22px;
}

@media (max-width: 900px) {
  .concern-status-tabs {
    display: flex;
    overflow-x: auto;
    scrollbar-width: none;
