.concern-status-tabs button:hover {
  background: light-dark(#f0fdf4, var(--hover));
  color: light-dark(#065f46, var(--primaryGreen));
  border-color: light-dark(rgba(16, 185, 129, 0.3), color-mix(in srgb, var(--successBorder) 30%, transparent));
}

.concern-status-tabs button.active {
  background: linear-gradient(135deg, light-dark(#0b4a38, var(--brandStrong)) 0%, light-dark(#06382a, var(--brandStrong)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  border-color: light-dark(#042f23, var(--successBorder));
  box-shadow: 0 4px 12px rgba(11, 74, 56, 0.28), inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.2), var(--highlight));
