/* Resident Concern Report Document Card */
.concern-record-card {
  position: relative;
  min-width: 0;
  max-width: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
  border-radius: 14px;
  background: light-dark(#ffffff, var(--surface));
  border: 1px solid light-dark(#dce8e2, var(--border));
  padding: 0;
  box-shadow:
    0 1px 3px rgba(6, 44, 32, 0.04),
    0 6px 16px -2px rgba(6, 44, 32, 0.06),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease, border-color 0.2s ease;
}

.concern-record-card:hover {
  transform: translateY(-3px);
  border-color: light-dark(#0b664c, var(--successBorder));
  box-shadow:
    0 4px 12px rgba(6, 44, 32, 0.08),
    0 16px 32px -4px rgba(6, 44, 32, 0.14),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.concern-record-card.selected {
  border-color: light-dark(#0b553e, var(--successBorder));
  box-shadow:
    0 0 0 2px #0b553e,
    0 14px 28px -4px rgba(6, 44, 32, 0.14),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

