  flex-direction: column;
  line-height: 1.15;
  flex: 1;
  min-width: 0;
}

.doc-card-mun-label {
  font: 700 8.5px 'Outfit', sans-serif;
  letter-spacing: 0.09em;
  color: light-dark(#a7f3d0, var(--primaryGreen));
  text-transform: uppercase;
}

.doc-card-mun-name {
  font: 900 14px 'Outfit', sans-serif;
  letter-spacing: 0.06em;
  color: light-dark(#ffffff, var(--onAccent));
}

.doc-card-mun-sub {
  font: 600 7.5px 'Outfit', sans-serif;
  letter-spacing: 0.05em;
  color: light-dark(#6ee7b7, var(--primaryGreen));
}

.doc-card-header-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-shrink: 0;
}

.doc-card-esugid-img {
  height: 38px;
  width: auto;
  max-width: 90px;
  object-fit: contain;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.25));
}

/* Card Watermark: Subtle Barili seal centered in background */
.concern-record-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: url("assets/barili-logoo.png") center 65% / 150px no-repeat;
