  pointer-events: none;
  z-index: 0;
}

/* Document Card Body */
.doc-card-body {
  position: relative;
  z-index: 1;
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
}

/* Subhead: Official Report + Main Title */
.doc-card-subhead {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.doc-official-tag {
  display: flex;
  align-items: center;
  gap: 6px;
  font: 800 9.5px 'Outfit', sans-serif;
  color: light-dark(#047857, var(--primaryGreen));
