}

/* Concern Type Tile: Light mint rounded tile with icon */
.doc-concern-type-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border-radius: 12px;
  background: light-dark(#eef7f2, var(--surfaceAlt));
  border: 1px solid light-dark(#dcefe4, var(--successBorder));
}

.doc-type-icon-gem {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: light-dark(#d1fae5, var(--successSurface));
