}

.doc-type-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.doc-field-caption {
  font: 700 9px 'Outfit', sans-serif;
  color: var(--textSecondary);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.doc-type-title {
  font: 850 13.5px 'Outfit', sans-serif;
  color: light-dark(#0f172a, var(--textPrimary));
  letter-spacing: 0.02em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 3 Clean Summary Rows: Resident, Barangay, Date Submitted */
.doc-summary-rows {
  display: flex;
  flex-direction: column;
  margin-top: 2px;
}

.doc-summary-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 4px;
  border-bottom: 1px solid light-dark(#f1f5f3, var(--border));
}

.doc-summary-row:last-child {
