}

.doc-sheet-letterhead,
.doc-sheet-green-rule,
.doc-sheet-report-lead,
.doc-sheet-meta-list,
.doc-sheet-arranged-content,
.doc-sheet-location-callout,
.doc-sheet-evidence-section,
.doc-sheet-official-footer {
  position: relative;
  z-index: 1;
}

/* Top Letterhead Layout (Left: barili-logoo.png, Center: Mun, Right: bagong-pilipinas.png) */
