  color: light-dark(#4b5563, var(--textSecondary));
  line-height: 1.2;
}

.doc-lgu-title {
  font: 900 19px 'Outfit', sans-serif;
  letter-spacing: 0.08em;
  color: light-dark(#0b3d2c, var(--textPrimary));
  line-height: 1.2;
