body .auth-card .auth-field > div:focus-within,
body .activation-form .auth-field > div:focus-within { border-color: light-dark(#0a9b72, var(--successBorder)); box-shadow: 0 0 0 4px rgba(10,155,114,.11), 0 8px 20px rgba(8,91,66,.08); }

