/* Staff login — single-viewport claymorphism composition.
   These selectors intentionally remain at the end of the stylesheet so the
   login is not affected by older authentication experiments above. */
body .auth-layout {
  position: relative;
  width: 100%;
  height: 100vh;
  height: 100dvh;
  min-height: 560px;
  overflow: hidden;
  grid-template-columns: minmax(360px, .86fr) minmax(500px, 1.14fr);
  background: light-dark(#eaf4ef, var(--surfaceAlt));
  isolation: isolate;
}

body .auth-brand-panel,
body .auth-form-panel {
  min-height: 0;
  height: 100%;
}

body .auth-brand-panel {
  padding: clamp(22px, 4vh, 42px) clamp(28px, 5vw, 72px);
  justify-content: center;
  background:
    radial-gradient(circle at 18% 12%, light-dark(rgba(50, 202, 145, .28), color-mix(in srgb, var(--brand) 28%, transparent)), transparent 34%),
    radial-gradient(circle at 86% 82%, light-dark(rgba(3, 47, 35, .52), color-mix(in srgb, var(--brandStrong) 52%, transparent)), transparent 42%),
    linear-gradient(145deg, light-dark(#087454, var(--brand)) 0%, light-dark(#075c45, var(--brandStrong)) 46%, light-dark(#043d2f, var(--brandStrong)) 100%);
  box-shadow: inset -1px 0 light-dark(rgba(255,255,255,.16), var(--highlight)), 18px 0 45px rgba(4,55,41,.13);
}

body .auth-brand-panel::before {
  width: min(48vw, 620px);
  height: min(48vw, 620px);
  top: -36%;
  left: -30%;
  border: 1px solid light-dark(rgba(255,255,255,.10), color-mix(in srgb, var(--border) 10%, transparent));
  background: light-dark(rgba(255,255,255,.035), color-mix(in srgb, var(--surface) 3.5%, transparent));
  filter: none;
}

body .auth-brand-panel::after {
  width: min(38vw, 480px);
  height: min(38vw, 480px);
  right: -25%;
  bottom: -32%;
  border: 1px solid light-dark(rgba(255,255,255,.08), color-mix(in srgb, var(--border) 8%, transparent));
  background: light-dark(rgba(255,255,255,.025), color-mix(in srgb, var(--surface) 2.5%, transparent));
  filter: none;
