  object-fit: contain;
  filter: drop-shadow(0 18px 28px rgba(0,0,0,.30));
  animation: auth-logo-drift 5.2s ease-in-out infinite;
  transform-origin: 50% 58%;
  will-change: transform;
}

.auth-brand-content {
