@keyframes auth-logo-drift {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(0deg); }
  35% { transform: translate3d(0, -7px, 0) rotate(-.45deg); }
  70% { transform: translate3d(0, -3px, 0) rotate(.35deg); }
