  border: 1px solid light-dark(rgba(255,255,255,.23), color-mix(in srgb, var(--border) 23%, transparent));
  border-radius: 14px;
  background: linear-gradient(145deg, light-dark(rgba(255,255,255,.17), color-mix(in srgb, var(--surface) 17%, transparent)), light-dark(rgba(255,255,255,.06), color-mix(in srgb, var(--surface) 6%, transparent)));
  color: light-dark(#effbf6, var(--onAccent));
  font-size: 20px;
  box-shadow: 7px 9px 18px rgba(1,35,25,.20), inset 1px 1px light-dark(rgba(255,255,255,.20), var(--highlight));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

body .auth-message-block--centered {
  max-width: 430px;
  margin-top: clamp(16px, 2.8vh, 28px);
}

body .auth-eyebrow {
  margin-bottom: clamp(10px, 1.5vh, 14px);
  padding: 6px 13px;
  background: light-dark(rgba(4,59,44,.22), color-mix(in srgb, var(--brandStrong) 22%, transparent));
  box-shadow: inset 1px 1px light-dark(rgba(255,255,255,.13), var(--highlight));
}

body .auth-message-block h1 {
  margin-bottom: clamp(7px, 1.2vh, 12px);
  font-size: clamp(32px, 5.1vh, 48px);
}

body .auth-message-block p {
  font-size: clamp(13px, 1.8vh, 16px);
}

body .auth-form-panel {
  position: relative;
  padding: clamp(22px, 4vh, 52px) clamp(26px, 6vw, 84px);
  overflow: hidden;
  background:
    radial-gradient(circle at 92% 8%, light-dark(rgba(16,167,121,.12), color-mix(in srgb, var(--brand) 12%, transparent)), transparent 26%),
    radial-gradient(circle at 10% 92%, light-dark(rgba(218,171,66,.10), color-mix(in srgb, var(--warningSolid) 10%, transparent)), transparent 23%),
