}

body .auth-form-panel::before,
body .auth-form-panel::after {
  content: "";
  position: absolute;
  z-index: 0;
  border-radius: 50%;
  pointer-events: none;
}

body .auth-form-panel::before {
  width: 270px;
  height: 270px;
  top: -150px;
  right: -80px;
  border: 34px solid light-dark(rgba(9,132,96,.055), color-mix(in srgb, var(--successBorder) 5.5%, transparent));
}

body .auth-form-panel::after {
  width: 190px;
  height: 190px;
  left: -88px;
  bottom: -110px;
  background: light-dark(rgba(9,132,96,.045), color-mix(in srgb, var(--brand) 4.5%, transparent));
  box-shadow: inset 12px 12px 24px light-dark(rgba(255,255,255,.45), var(--highlight));
}

body .auth-card {
  position: relative;
  z-index: 1;
  width: min(100%, 500px);
  max-height: calc(100dvh - 44px);
  padding: clamp(24px, 3.7vh, 38px);
  overflow: hidden;
  border: 1px solid light-dark(rgba(255,255,255,.92), color-mix(in srgb, var(--border) 92%, transparent));
  border-radius: clamp(26px, 3vw, 36px);
  background: linear-gradient(145deg, light-dark(rgba(255,255,255,.90), color-mix(in srgb, var(--surface) 90%, transparent)), light-dark(rgba(242,249,246,.78), color-mix(in srgb, var(--surfaceAlt) 78%, transparent)));
  box-shadow:
    20px 24px 52px rgba(7,63,47,.13),
    -12px -12px 30px light-dark(rgba(255,255,255,.82), var(--highlight)),
    inset 2px 2px 2px light-dark(rgba(255,255,255,.96), var(--highlight)),
    inset -2px -2px 5px rgba(7,80,58,.055);
  backdrop-filter: blur(20px) saturate(125%);
  -webkit-backdrop-filter: blur(20px) saturate(125%);
}

body .auth-card::before {
  content: "";
  position: absolute;
  inset: 10px;
  z-index: -1;
  border: 1px solid light-dark(rgba(10,139,100,.08), color-mix(in srgb, var(--successBorder) 8%, transparent));
  border-radius: calc(clamp(26px, 3vw, 36px) - 9px);
  pointer-events: none;
}

body .auth-card-heading {
  gap: 14px;
  margin-bottom: clamp(18px, 2.8vh, 27px);
}

body .auth-card .auth-card-heading .auth-icon {
  width: 54px;
  height: 54px;
  border: 1px solid light-dark(rgba(255,255,255,.9), color-mix(in srgb, var(--border) 90%, transparent));
  border-radius: 18px;
  background: linear-gradient(145deg, light-dark(#e2f4eb, var(--successSurface)), light-dark(#fbfefc, var(--surface)));
  box-shadow: 8px 9px 19px rgba(7,75,54,.11), -5px -5px 14px light-dark(#fff, var(--highlight)), inset 2px 2px 3px light-dark(#fff, var(--highlight));
}

body .auth-card-heading h2 {
  font-size: clamp(25px, 3.4vh, 32px);
}

body .auth-card .auth-field {
  gap: 6px;
  margin-bottom: clamp(12px, 2vh, 17px);
}

body .auth-card .auth-field > div {
  min-height: 52px;
  border-color: light-dark(rgba(18,111,82,.18), color-mix(in srgb, var(--successBorder) 18%, transparent));
  border-radius: 16px;
  background: light-dark(rgba(245,250,247,.84), color-mix(in srgb, var(--surfaceAlt) 84%, transparent));
  box-shadow: inset 4px 4px 8px rgba(6,73,52,.065), inset -5px -5px 10px light-dark(rgba(255,255,255,.96), var(--highlight));
}

body .auth-card .auth-field > div:focus-within {
  background: light-dark(rgba(255,255,255,.94), color-mix(in srgb, var(--surface) 94%, transparent));
  box-shadow: inset 2px 2px 5px rgba(6,73,52,.045), 0 0 0 4px rgba(10,155,114,.10), 0 9px 20px rgba(8,91,66,.08);
}

body .auth-card .button--primary {
  height: 54px;
  margin-top: 4px;
  border: 1px solid light-dark(rgba(5,89,64,.25), color-mix(in srgb, var(--successBorder) 25%, transparent));
  border-radius: 17px;
  background: linear-gradient(145deg, light-dark(#0ba77a, var(--brand)), light-dark(#087252, var(--brand)));
  box-shadow: 0 13px 24px rgba(8,116,84,.24), inset 1px 2px 3px light-dark(rgba(255,255,255,.32), var(--highlight)), inset -2px -3px 5px rgba(3,61,43,.18);
}

body .auth-helper-row {
  margin-top: clamp(13px, 2vh, 19px);
}

body .auth-card .form-message:empty {
  display: none;
}

body .auth-card .form-message {
  margin: 0 0 12px;
  padding: 11px 13px;
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.45;
  text-align: left;
}

body .auth-card .form-message.error {
  border: 1px solid light-dark(#efb7b7, var(--errorBorder));
  background: light-dark(#fff0f0, var(--surfaceAlt));
  color: light-dark(#a51f28, var(--error));
  font-weight: 700;
}

body .auth-card .form-message.success {
  border: 1px solid light-dark(#b7ddcb, var(--successBorder));
  background: light-dark(#eefaf3, var(--surfaceAlt));
  color: light-dark(#087454, var(--primaryGreen));
}

