/* Hyper-Tactile Glass Overrides for Staff Activation (2026 Municipal Glass) */
.activation-layout {
  background:
    radial-gradient(circle at 15% 15%, light-dark(rgba(10, 167, 121, 0.22), color-mix(in srgb, var(--brand) 22%, transparent)) 0%, transparent 40%),
    radial-gradient(circle at 85% 85%, light-dark(rgba(36, 107, 178, 0.16), color-mix(in srgb, var(--infoSolid) 16%, transparent)) 0%, transparent 40%),
    radial-gradient(circle at 50% 50%, light-dark(rgba(226, 154, 24, 0.08), color-mix(in srgb, var(--warningSolid) 8%, transparent)) 0%, transparent 60%),
    linear-gradient(135deg, light-dark(#04261d, var(--brandStrong)) 0%, light-dark(#063d2d, var(--brandStrong)) 100%) !important;
}

.activation-shell {
  border: 1px solid light-dark(rgba(255, 255, 255, 0.8), color-mix(in srgb, var(--border) 80%, transparent)) !important;
  background: light-dark(rgba(255, 255, 255, 0.76), color-mix(in srgb, var(--surface) 76%, transparent)) !important;
  backdrop-filter: blur(22px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(22px) saturate(140%) !important;
  box-shadow:
    0 28px 75px rgba(7, 60, 43, 0.18),
    0 10px 30px rgba(0, 0, 0, 0.05),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.95), var(--highlight)) !important;
}

.activation-progress b {
  width: 34px !important;
  height: 34px !important;
  border: 1px solid light-dark(rgba(255, 255, 255, 0.6), color-mix(in srgb, var(--border) 60%, transparent)) !important;
  background: light-dark(rgba(255, 255, 255, 0.45), color-mix(in srgb, var(--surface) 45%, transparent)) !important;
  box-shadow:
    inset 3px 3px 6px light-dark(rgba(255, 255, 255, 0.9), var(--highlight)),
    inset -3px -3px 6px rgba(0, 0, 0, 0.04),
    0 6px 12px rgba(0, 0, 0, 0.06) !important;
  backdrop-filter: blur(12px) !important;
  color: light-dark(var(--green-900), var(--primaryGreen)) !important;
  font-weight: 800 !important;
}

.activation-progress .active b {
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)), light-dark(#087454, var(--brand))) !important;
  border-color: light-dark(rgba(255, 255, 255, 0.3), color-mix(in srgb, var(--border) 30%, transparent)) !important;
  color: light-dark(white, var(--onAccent)) !important;
  box-shadow:
    0 10px 24px rgba(8, 116, 84, 0.35),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.45), var(--highlight)) !important;
}

.activation-progress i {
  background: light-dark(rgba(10, 167, 121, 0.2), color-mix(in srgb, var(--brand) 20%, transparent)) !important;
  height: 2px !important;
  margin-top: 17px !important;
}

.activation-icon {
  background: linear-gradient(145deg, light-dark(rgba(228, 245, 237, 0.9), color-mix(in srgb, var(--successSurface) 90%, transparent)), light-dark(rgba(255, 255, 255, 0.95), color-mix(in srgb, var(--surface) 95%, transparent))) !important;
  box-shadow:
    0 14px 32px rgba(8, 116, 84, 0.18),
    inset 0 1px 0 light-dark(#fff, var(--highlight)) !important;
  filter: saturate(140%) !important;
  border: 1px solid light-dark(rgba(255, 255, 255, 0.8), color-mix(in srgb, var(--border) 80%, transparent)) !important;
}

.activation-brand img {
  filter: drop-shadow(0 10px 18px rgba(4, 65, 47, 0.22)) saturate(130%) !important;
}

.activation-heading h1 {
  letter-spacing: -0.04em !important;
  color: light-dark(var(--green-950), var(--primaryGreen)) !important;
}

/* Announcement composer — scoped claymorphism treatment. */
#announcementComposerPanel {
  position: relative;
  isolation: isolate;
  width: min(100%, 980px);
  max-width: 980px;
  margin: 18px auto 30px;
  overflow: hidden;
  border: 1px solid light-dark(rgba(255,255,255,.92), color-mix(in srgb, var(--border) 92%, transparent));
  border-radius: 30px;
  background:
    radial-gradient(circle at 94% 4%, light-dark(rgba(19,165,119,.09), color-mix(in srgb, var(--brand) 9%, transparent)), transparent 260px),
    linear-gradient(145deg, light-dark(rgba(255,255,255,.96), color-mix(in srgb, var(--surface) 96%, transparent)), light-dark(rgba(239,248,244,.91), color-mix(in srgb, var(--surfaceAlt) 91%, transparent)));
  box-shadow:
    20px 24px 54px rgba(8,65,48,.13),
    -10px -10px 28px light-dark(rgba(255,255,255,.82), var(--highlight)),
    inset 2px 2px 3px light-dark(rgba(255,255,255,.98), var(--highlight)),
    inset -2px -2px 5px rgba(7,80,58,.045);
  backdrop-filter: blur(20px) saturate(125%);
  -webkit-backdrop-filter: blur(20px) saturate(125%);
}

#announcementComposerPanel::before {
  content: "";
  position: absolute;
  z-index: -1;
  width: 240px;
  height: 240px;
  top: -145px;
  right: -100px;
  border: 30px solid light-dark(rgba(8,122,89,.045), color-mix(in srgb, var(--successBorder) 4.5%, transparent));
  border-radius: 50%;
  pointer-events: none;
}

#announcementComposerPanel .focus-header {
  min-height: 96px;
  padding: 20px 28px;
  border-bottom: 1px solid light-dark(rgba(8,116,84,.13), color-mix(in srgb, var(--successBorder) 13%, transparent));
  background: linear-gradient(135deg, light-dark(rgba(230,247,239,.92), color-mix(in srgb, var(--successSurface) 92%, transparent)), light-dark(rgba(255,255,255,.76), color-mix(in srgb, var(--surface) 76%, transparent)));
  box-shadow: inset 0 -1px light-dark(rgba(255,255,255,.76), var(--highlight));
}

#announcementComposerPanel .focus-header h2 {
  align-self: end;
  color: light-dark(#0b3529, var(--textPrimary));
  font-size: clamp(23px,2.2vw,29px);
  letter-spacing: -.025em;
}

#announcementComposerPanel .focus-header p {
  align-self: start;
}

#announcementComposerPanel .focus-header .icon-button {
  width: 46px;
  height: 46px;
  flex-basis: 46px;
  border: 1px solid light-dark(rgba(8,116,84,.13), color-mix(in srgb, var(--successBorder) 13%, transparent));
  border-radius: 15px;
  background: linear-gradient(145deg,light-dark(#f8fcfa, var(--surface)),light-dark(#e4f2eb, var(--surfaceAlt)));
  color: light-dark(#41665a, var(--textSecondary));
  box-shadow: 6px 7px 15px rgba(7,75,54,.09), -4px -4px 11px light-dark(#fff, var(--highlight)), inset 1px 1px 2px light-dark(#fff, var(--highlight));
}

#announcementComposerPanel .focus-header .icon-button:hover,
#announcementComposerPanel .focus-header .icon-button:focus-visible {
  background: light-dark(#dcf2e7, var(--hover));
  color: light-dark(#087454, var(--primaryGreen));
  transform: translateY(-1px);
}

#announcementComposerPanel .form-stepper {
  position: relative;
  padding: 22px clamp(28px,6vw,72px);
  border-bottom: 1px solid light-dark(rgba(8,116,84,.11), color-mix(in srgb, var(--successBorder) 11%, transparent));
  background: light-dark(rgba(248,252,250,.72), color-mix(in srgb, var(--surface) 72%, transparent));
}

#announcementComposerPanel .form-stepper li {
  font-size: 14px;
  letter-spacing: .01em;
}

#announcementComposerPanel .form-stepper b {
  width: 38px;
  height: 38px;
  border: 1px solid light-dark(rgba(255,255,255,.88), color-mix(in srgb, var(--border) 88%, transparent));
  background: linear-gradient(145deg,light-dark(#edf4f1, var(--surfaceAlt)),light-dark(#dfeae5, var(--surfaceAlt)));
  box-shadow: 5px 6px 12px rgba(7,75,54,.08), -4px -4px 10px light-dark(#fff, var(--highlight)), inset 1px 1px 2px light-dark(#fff, var(--highlight));
}

#announcementComposerPanel .form-stepper li.active b,
#announcementComposerPanel .form-stepper li.complete b {
  border-color: light-dark(rgba(5,101,73,.34), color-mix(in srgb, var(--successBorder) 34%, transparent));
  background: linear-gradient(145deg,light-dark(#0c9a70, var(--brand)),light-dark(#07684c, var(--brandStrong)));
  box-shadow: 0 8px 17px rgba(8,116,84,.25), inset 1px 2px 3px light-dark(rgba(255,255,255,.25), var(--highlight)), inset -2px -2px 4px rgba(3,61,43,.18);
}

#announcementComposerPanel .form-stepper li:not(:last-child)::after {
  height: 3px;
  border-radius: 999px;
  background: light-dark(#dbe8e2, var(--surfaceAlt));
  box-shadow: inset 1px 1px 2px rgba(6,70,51,.08);
}

#announcementComposerPanel .form-stepper li.complete::after {
  background: linear-gradient(90deg,light-dark(#0b9b71, var(--brand)),light-dark(#55c39d, var(--brand)));
