#announcementComposerPanel .optional-fields,
#announcementComposerPanel .barangay-picker,
#announcementComposerPanel .audience-summary,
#announcementComposerPanel .switch-row {
  border-color: light-dark(rgba(17,104,78,.15), color-mix(in srgb, var(--successBorder) 15%, transparent));
