  box-shadow: 5px 6px 13px rgba(7,75,54,.06), -4px -4px 10px light-dark(#fff, var(--highlight)), inset 1px 1px 2px light-dark(#fff, var(--highlight));
}

#announcementComposerPanel .choice-group button.active {
  border-color: light-dark(#0b8a65, var(--successBorder));
  background: linear-gradient(145deg,light-dark(#d8f2e6, var(--successSurface)),light-dark(#edf9f3, var(--surfaceAlt)));
  color: light-dark(#075e45, var(--primaryGreen));
  box-shadow: inset 3px 3px 7px rgba(7,93,67,.09), inset -3px -3px 7px light-dark(#fff, var(--highlight)), 0 7px 16px rgba(8,116,84,.09);
}

#announcementComposerPanel .wizard-actions {
  min-height: 86px;
  padding: 15px clamp(24px,4vw,42px);
  border-top: 1px solid light-dark(rgba(8,116,84,.12), color-mix(in srgb, var(--successBorder) 12%, transparent));
  background: linear-gradient(180deg,light-dark(rgba(250,253,251,.86), color-mix(in srgb, var(--surface) 86%, transparent)),light-dark(rgba(235,246,240,.94), color-mix(in srgb, var(--surfaceAlt) 94%, transparent)));
  box-shadow: 0 -8px 22px rgba(8,65,48,.035), inset 0 1px light-dark(#fff, var(--highlight));
}

#announcementComposerPanel .wizard-actions .button {
  min-height: 50px;
  border-radius: 15px;
}

#announcementComposerPanel .wizard-actions .button--primary {
