@media (max-width: 760px) {
  #announcementComposerPanel {
    width: 100%;
    margin-top: 8px;
    border-radius: 22px;
  }

  #announcementComposerPanel .focus-header {
    min-height: 82px;
    padding: 15px 16px;
  }

  #announcementComposerPanel .focus-header h2 {
