/* ==========================================================================
   RESIDENT VERIFICATION: 3D Aesthetic, Classy, Direct & Ergonomic Workspace
   ========================================================================== */

.resident-verification-page {
  animation: fadeInVerification 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}

.verification-command-bar {
  margin-bottom: 20px;
}

@keyframes fadeInVerification {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulseEmeraldDot {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.65); }
  70% { transform: scale(1); box-shadow: 0 0 0 6px rgba(16, 185, 129, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

/* Header & Back Navigation */
.resident-verification-page .people-queue-page-header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 20px;
}

.resident-verification-page .people-back-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 999px;
  border: 1.2px solid light-dark(#d4e5dc, var(--border));
  background: linear-gradient(180deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7faf9, var(--surfaceAlt)) 100%);
  color: light-dark(#123e30, var(--textPrimary));
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(11, 73, 55, 0.04), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.resident-verification-page .people-back-button:hover {
  transform: translateX(-3px);
  border-color: light-dark(#10b981, var(--successBorder));
  color: light-dark(#047857, var(--primaryGreen));
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.16), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.resident-verification-page .people-back-button:active {
  transform: translateX(-1px) scale(0.98);
}

.resident-verification-page .people-back-button .material-symbols-rounded {
  font-size: 18px;
  transition: transform 0.2s ease;
}

.resident-verification-page .people-back-button:hover .material-symbols-rounded {
  transform: translateX(-2px);
}

/* Heading block */
.resident-verification-page .people-queue-page-heading {
  display: flex;
  align-items: center;
  gap: 16px;
}

.resident-verification-page .queue-icon-3d,
.resident-verification-page .queue-icon {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  border-radius: 16px;
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 45%, light-dark(#046c4e, var(--brand)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  box-shadow: 0 8px 20px -3px rgba(5, 150, 105, 0.42), inset 0 1.5px 1.5px light-dark(rgba(255, 255, 255, 0.45), var(--highlight));
  position: relative;
}

.resident-verification-page .queue-icon-3d .material-symbols-rounded,
.resident-verification-page .queue-icon .material-symbols-rounded {
  font-size: 27px;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.2));
}

.resident-verification-page .queue-heading-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.resident-verification-page .queue-tag-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 3px;
}

.resident-verification-page .eyebrow-pill,
.resident-verification-page #verificationScopeEyebrow {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  background: light-dark(#e8f7f1, var(--surfaceAlt));
  border: 1px solid light-dark(#c5ebd8, var(--successBorder));
  color: light-dark(#047857, var(--primaryGreen));
  font-family: 'Outfit', sans-serif;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.resident-verification-page .status-registry-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  background: light-dark(#f1f6f4, var(--surfaceAlt));
  border: 1px solid light-dark(#dae7e1, var(--border));
  color: light-dark(#4b6a5d, var(--textSecondary));
  font-family: 'Outfit', sans-serif;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.resident-verification-page .registry-pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: light-dark(#087f60, var(--brand));
  animation: pulseEmeraldDot 2.2s infinite;
}

.resident-verification-page .queue-heading-title,
.resident-verification-page .people-queue-page-heading h2 {
  font-family: 'Outfit', sans-serif;
  font-size: 26px;
  font-weight: 850;
  letter-spacing: -0.025em;
  color: light-dark(#0d2a20, var(--textPrimary));
  margin: 0;
  line-height: 1.2;
}

.resident-verification-page .queue-heading-desc,
.resident-verification-page #verificationPageDescription {
  font-size: 13px;
  color: light-dark(#557265, var(--textSecondary));
  margin: 3px 0 0;
  font-weight: 500;
  line-height: 1.35;
}

/* Surface Shell */
.resident-verification-surface {
  background: light-dark(#ffffff, var(--surface));
  border-radius: 22px;
  border: 1.5px solid light-dark(#d8e8e0, var(--border));
  box-shadow: 0 20px 48px -12px rgba(8, 63, 48, 0.08), 0 2px 6px rgba(0, 0, 0, 0.02);
  overflow: hidden;
  transition: box-shadow 0.3s ease;
}

/* Stat Cards 3D Grid */
.resident-verification-page .verification-count-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  padding: 18px 20px;
  background: linear-gradient(180deg, light-dark(#f8fbf9, var(--surface)) 0%, light-dark(#ffffff, var(--surface)) 100%);
  border-bottom: 1.5px solid light-dark(#e5eee9, var(--border));
}

.account-approval-page .verification-count-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  padding: 18px 20px;
  background: linear-gradient(180deg, light-dark(#f8fbf9, var(--surface)) 0%, light-dark(#ffffff, var(--surface)) 100%);
  border-bottom: 1.5px solid light-dark(#e5eee9, var(--border));
}

.resident-verification-page .verification-stat,
.account-approval-page .verification-stat {
  position: relative;
  min-height: 104px;
  padding: 16px 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  overflow: hidden;
  border-radius: 20px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7fbf9, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#d4e5dd, var(--border));
  box-shadow:
    0 2px 6px rgba(6, 44, 32, 0.04),
    0 10px 24px -4px rgba(6, 44, 32, 0.07),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.2s ease;
  user-select: none;
}

/* Category Accent Colors */
.resident-verification-page .verification-stat--pending,
.account-approval-page .verification-stat--pending { --card-accent: light-dark(#995b00, var(--warning)); }
.resident-verification-page .verification-stat--verified,
.account-approval-page .verification-stat--verified { --card-accent: light-dark(#087454, var(--primaryGreen)); }
.resident-verification-page .verification-stat--attention,
.account-approval-page .verification-stat--attention { --card-accent: light-dark(#f43f5e, var(--error)); }
.resident-verification-page .verification-stat--rejected,
.account-approval-page .verification-stat--rejected { --card-accent: light-dark(#b52d38, var(--error)); }

.verification-reason--rejected {
  color: light-dark(#b52d38, var(--error)) !important;
  font-weight: 600;
}

/* Bottom Glowing Accent Line matching Picture 1 */
.resident-verification-page .verification-stat::after,
.account-approval-page .verification-stat::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 3.5px;
  background: var(--card-accent, light-dark(#087f60, var(--brand)));
  opacity: 0.8;
  transition: height 0.2s ease, opacity 0.2s ease;
}

/* Ambient Radial Corner Glow */
.resident-verification-page .verification-stat::before,
.account-approval-page .verification-stat::before {
  content: "";
  position: absolute;
  top: -35px;
  right: -35px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--card-accent) 22%, transparent) 0%, transparent 70%);
  pointer-events: none;
  opacity: 0.6;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.resident-verification-page .verification-stat:hover,
.account-approval-page .verification-stat:hover {
  transform: translateY(-4px) scale(1.008);
  border-color: color-mix(in srgb, var(--card-accent) 45%, light-dark(white, var(--border)));
  box-shadow:
    0 6px 14px rgba(6, 44, 32, 0.06),
    0 18px 36px -6px rgba(6, 44, 32, 0.14),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.resident-verification-page .verification-stat:hover::before,
.account-approval-page .verification-stat:hover::before {
  opacity: 1;
  transform: scale(1.15);
}

.resident-verification-page .verification-stat:hover::after,
.resident-verification-page .verification-stat.is-active::after,
.account-approval-page .verification-stat:hover::after,
.account-approval-page .verification-stat.is-active::after,
.account-approval-page .verification-stat.active::after {
  height: 4.5px;
  opacity: 1;
}

/* Selected / Active State matching Picture 1 */
.resident-verification-page .verification-stat.is-active,
.account-approval-page .verification-stat.is-active,
.account-approval-page .verification-stat.active {
  border-color: var(--card-accent);
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, color-mix(in srgb, var(--card-accent) 6%, light-dark(white, var(--surface))) 100%);
  box-shadow:
    0 4px 12px rgba(6, 44, 32, 0.05),
    0 14px 30px -4px rgba(6, 44, 32, 0.12),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight)),
    0 0 0 1.5px color-mix(in srgb, var(--card-accent) 35%, transparent);
}

.resident-verification-page .verification-stat:focus-visible,
.account-approval-page .verification-stat:focus-visible {
  outline: 3px solid light-dark(rgba(16, 185, 129, 0.25), color-mix(in srgb, var(--successBorder) 25%, transparent));
  outline-offset: 2px;
}

/* 3D Raised Icon Medallion matching Picture 1 */
.resident-verification-page .verification-stat-medallion,
.resident-verification-page .verification-stat > .material-symbols-rounded,
.account-approval-page .verification-stat-medallion,
.account-approval-page .verification-stat > .material-symbols-rounded {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, color-mix(in srgb, var(--card-accent) 14%, light-dark(white, var(--surface))) 100%);
  border: 1.5px solid color-mix(in srgb, var(--card-accent) 26%, light-dark(white, var(--border)));
  box-shadow:
    0 4px 10px color-mix(in srgb, var(--card-accent) 20%, transparent),
    inset 0 1px 1px light-dark(#ffffff, var(--highlight));
  color: var(--card-accent);
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.resident-verification-page .verification-stat-medallion .material-symbols-rounded,
.resident-verification-page .verification-stat > .material-symbols-rounded,
.account-approval-page .verification-stat-medallion .material-symbols-rounded,
.account-approval-page .verification-stat > .material-symbols-rounded {
  font-size: 24px;
  color: var(--card-accent);
}

.resident-verification-page .verification-stat:hover .verification-stat-medallion,
.resident-verification-page .verification-stat:hover > .material-symbols-rounded,
.account-approval-page .verification-stat:hover .verification-stat-medallion,
.account-approval-page .verification-stat:hover > .material-symbols-rounded {
  transform: scale(1.08) rotate(3deg);
}

/* Numbers and Labels matching Picture 1 typography & hierarchy */
.resident-verification-page .verification-stat-info,
.account-approval-page .verification-stat-info {
  display: flex;
  flex-direction: column;
}

.resident-verification-page .verification-stat-info small,
.account-approval-page .verification-stat-info small {
  order: 1;
  display: block;
  margin: 0 0 2px;
  font-family: 'Outfit', sans-serif;
  font-size: 11.5px;
  font-weight: 750;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: light-dark(#4b6b5d, var(--textSecondary));
}

.resident-verification-page .verification-stat-info strong,
.account-approval-page .verification-stat-info strong {
  order: 2;
  display: block;
  font-family: 'Outfit', sans-serif;
  font-size: 28px;
  font-weight: 850;
  letter-spacing: -0.03em;
  color: light-dark(#0c291e, var(--textPrimary));
  line-height: 1.1;
}

.resident-verification-page .verification-stat-active-pill,
.account-approval-page .verification-stat-active-pill {
  display: none !important;
}

/* Tools Bar: Search and Sort Controls */
.resident-verification-page .verification-tools,
.account-approval-page .verification-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 22px;
  background: light-dark(#fbfdfc, var(--surface));
  border-bottom: 1.5px solid light-dark(#e6efea, var(--border));
}

.resident-verification-page .verification-filter-anchor { position: relative; margin-left: auto; }
.resident-verification-page .verification-filter-button {
  min-height: 42px;
  padding: 0 14px;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 750;
}
.resident-verification-page .verification-filter-button.has-filters { border-color: light-dark(#0a8767, var(--successBorder)); background: light-dark(#e8f7f0, var(--surfaceAlt)); color: light-dark(#075c44, var(--primaryGreen)); }
.resident-verification-page .verification-filter-count {
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  background: light-dark(#087458, var(--brand));
  color: light-dark(#fff, var(--onAccent));
  font-size: 11px;
}
.resident-verification-page .verification-filter-count[hidden],
.resident-verification-page .verification-filter-popover[hidden],
.resident-verification-page .verification-filter-field[hidden] { display: none; }
.resident-verification-page .verification-filter-popover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 10px);
  right: 0;
  width: min(290px, calc(100vw - 48px));
  padding: 16px;
  display: grid;
  gap: 12px;
  border: 1px solid light-dark(#cde0d7, var(--border));
  border-radius: 16px;
  background: light-dark(#fff, var(--surface));
  box-shadow: 0 18px 42px rgba(6, 44, 32, .18);
}
