.resident-verification-page .verification-search-box:focus-within .search-icon-glow,
.resident-verification-page .verification-tools .page-search:focus-within .material-symbols-rounded,
.account-approval-page .verification-search-box:focus-within .search-icon-glow,
.account-approval-page .verification-tools .page-search:focus-within .material-symbols-rounded {
