  padding: 4px 12px;
  border-radius: 999px;
  font-family: 'Outfit', sans-serif;
  font-size: 11.5px;
  font-weight: 750;
  letter-spacing: 0.02em;
  border: 1px solid transparent;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.04);
}

.status-pill--3d .status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.status-pill--3d.verified,
.status-pill--3d.approved {
  background: light-dark(#e6f7ef, var(--successSurface));
  color: light-dark(#047857, var(--primaryGreen));
  border-color: light-dark(#a7f3d0, var(--successBorder));
}

.status-pill--3d.deactivated {
  background: light-dark(#f1f5f4, var(--surfaceAlt));
  color: light-dark(#64748b, var(--textSecondary));
  border-color: light-dark(#dce5e1, var(--border));
}

#page-directory.is-barangay-team .resident-avatar-medallion--muted {
  background: linear-gradient(135deg, light-dark(#a9b9b2, var(--surfaceAlt)), light-dark(#70877c, var(--surfaceAlt)));
  box-shadow: 0 3px 8px rgba(48, 68, 58, 0.12);
}

.status-pill--3d.submitted,
.status-pill--3d.under_review,
.status-pill--3d.pending {
  background: light-dark(#fef3c7, var(--warningSurface));
  color: light-dark(#b45309, var(--warning));
  border-color: light-dark(#fde68a, var(--warningBorder));
}

.status-pill--3d.additional_document_required,
.status-pill--3d.attention {
  background: light-dark(#ffe4e6, var(--errorSurface));
  color: light-dark(#be123c, var(--error));
  border-color: light-dark(#fecdd3, var(--errorBorder));
}

.status-pill--3d.rejected {
  background: light-dark(#fee2e2, var(--errorSurface));
  color: light-dark(#b91c1c, var(--error));
  border-color: light-dark(#fca5a5, var(--errorBorder));
}

/* Action Buttons 3D */
.verification-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 11px;
  font-family: 'Outfit', sans-serif;
  font-size: 12.5px;
  font-weight: 750;
