  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 50%, light-dark(#047857, var(--brand)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  border: none;
  box-shadow: 0 4px 12px rgba(5, 150, 105, 0.32), inset 0 1px 1px light-dark(rgba(255, 255, 255, 0.4), var(--highlight));
}

