}

.verification-action-btn--review:active {
  transform: translateY(0) scale(0.97);
}

/* Details Secondary 3D */
.verification-action-btn--view {
  background: light-dark(#f4f8f6, var(--surfaceAlt));
  color: light-dark(#174032, var(--textPrimary));
