  box-shadow: 0 2px 6px rgba(11, 73, 55, 0.03);
}

.verification-action-btn--view:hover {
  transform: translateY(-2px);
  background: light-dark(#ffffff, var(--hover));
  border-color: light-dark(#10b981, var(--successBorder));
  color: light-dark(#047857, var(--primaryGreen));
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.12);
}

.verification-action-btn--view:active {
  transform: translateY(0) scale(0.97);
}

