}

.resident-verification-page .verification-empty-emblem,
.account-approval-page .verification-empty-emblem {
  width: 68px;
  height: 68px;
  margin: 0 auto 16px;
  border-radius: 20px;
  background: linear-gradient(135deg, light-dark(#e8f7f1, var(--surfaceAlt)) 0%, light-dark(#d5f2e5, var(--successSurface)) 100%);
  color: light-dark(#087454, var(--primaryGreen));
  display: grid;
  place-items: center;
  box-shadow: 0 10px 24px -4px rgba(5, 150, 105, 0.2), inset 0 1.5px 1.5px light-dark(rgba(255, 255, 255, 0.8), var(--highlight));
}

.resident-verification-page .verification-empty-emblem .material-symbols-rounded,
.account-approval-page .verification-empty-emblem .material-symbols-rounded {
