}

.resident-verification-review-summary > .material-symbols-rounded,
.resident-verification-review-summary .verification-modal-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 15px;
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  font-size: 26px;
  box-shadow: 0 6px 16px -2px rgba(5, 150, 105, 0.38), inset 0 1.5px 1.5px light-dark(rgba(255, 255, 255, 0.4), var(--highlight));
}

.resident-verification-review-summary strong {
  font-family: 'Outfit', sans-serif;
  font-size: 16px;
  font-weight: 800;
  color: light-dark(#0c2b20, var(--textPrimary));
  display: block;
}

.resident-verification-review-summary small {
  font-size: 11px;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: light-dark(#047857, var(--primaryGreen));
  display: block;
}

.resident-verification-review-summary span {
  font-size: 12.5px;
  color: light-dark(#5c7b6e, var(--textSecondary));
}

.modal-btn-3d {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: 13px;
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 750;
  cursor: pointer;
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.modal-btn-3d .material-symbols-rounded {
  font-size: 19px;
}

.modal-btn-3d.button--danger {
  background: linear-gradient(135deg, light-dark(#f43f5e, var(--errorSolid)) 0%, light-dark(#e11d48, var(--errorSolid)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  border: none;
  box-shadow: 0 4px 14px rgba(225, 29, 72, 0.32), inset 0 1px 1px light-dark(rgba(255, 255, 255, 0.35), var(--highlight));
}

.modal-btn-3d.button--danger:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(225, 29, 72, 0.45);
}

.modal-btn-3d.button--danger:active {
  transform: translateY(0) scale(0.97);
}

.modal-btn-3d.button--primary {
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  border: none;
  box-shadow: 0 4px 14px rgba(5, 150, 105, 0.35), inset 0 1px 1px light-dark(rgba(255, 255, 255, 0.4), var(--highlight));
}

.modal-btn-3d.button--primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(5, 150, 105, 0.48);
