@media (max-width: 960px) {
  .resident-verification-page .verification-count-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    padding: 12px;
  }
}
@media (max-width: 820px) {
  .resident-verification-page .verification-count-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    padding: 12px;
  }
  .resident-verification-page .verification-stat {
    padding: 12px;
    gap: 10px;
  }
  .resident-verification-page .verification-stat-medallion,
  .resident-verification-page .verification-stat > .material-symbols-rounded {
    width: 38px;
    height: 38px;
    flex-basis: 38px;
    font-size: 20px;
  }
  .resident-verification-page .verification-stat strong {
    font-size: 22px;
  }
  .resident-verification-page .verification-stat small {
