/* Account Approvals: Premium 3D Workspace */
.account-approval-surface {
  overflow: hidden;
  border: 1.5px solid light-dark(#d4e7dc, var(--border)) !important;
  border-radius: 22px !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  box-shadow: 0 14px 40px rgba(6, 44, 32, 0.07), 0 2px 8px rgba(6, 44, 32, 0.03) !important;
}

.account-approval-header-bar {
  padding: 14px 22px;
  background: linear-gradient(180deg, light-dark(#fbfdfc, var(--surface)) 0%, light-dark(#f2f8f4, var(--surfaceAlt)) 100%);
  border-bottom: 1.5px solid light-dark(#dbeae1, var(--border));
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

.account-approval-page .account-approval-tabs {
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  padding: 4px !important;
  background: light-dark(#e7f2ec, var(--surfaceAlt)) !important;
  border-radius: 14px !important;
  border: 1px solid light-dark(#cce1d5, var(--border)) !important;
