  margin: 0 auto 16px;
  display: grid;
  place-items: center;
  border-radius: 20px;
  background: linear-gradient(145deg, light-dark(#e6f7ef, var(--successSurface)) 0%, light-dark(#cbf2df, var(--successSurface)) 100%);
  border: 2px solid light-dark(#a3e2c2, var(--successBorder));
