  border: 1.5px solid light-dark(#d2e4da, var(--border)) !important;
  box-shadow:
    0 4px 14px rgba(6, 44, 32, 0.05),
    0 12px 28px -6px rgba(6, 44, 32, 0.08),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight)) !important;
