  background: linear-gradient(145deg, light-dark(#eaf7ef, var(--surfaceAlt)) 0%, light-dark(#d8f1e3, var(--successSurface)) 100%);
  border: 1.5px solid light-dark(#bce1ce, var(--successBorder));
  color: light-dark(#065f46, var(--primaryGreen));
  font-family: 'Outfit', sans-serif;
  font-size: 12px;
  font-weight: 750;
  box-shadow: 0 1px 3px rgba(6, 44, 32, 0.05), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.barangay-status-badge .material-symbols-rounded {
