/* 3D Barangay Checklist Grid */
.barangay-3d-checklist {
  max-height: 220px !important;
  overflow-y: auto !important;
  padding: 10px 12px !important;
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 8px !important;
  scrollbar-width: thin;
  scrollbar-color: light-dark(#a3d4bd, var(--textSecondary)) transparent;
}

.barangay-3d-checklist::-webkit-scrollbar {
  width: 5px;
}

.barangay-3d-checklist::-webkit-scrollbar-thumb {
  background: light-dark(#a3d4bd, var(--successSurface));
  border-radius: 10px;
}

.barangay-3d-checklist::-webkit-scrollbar-track {
  background: transparent;
}

.barangay-3d-tile {
  position: relative;
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  padding: 8px 12px !important;
  min-height: 42px !important;
  border-radius: 12px !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  border: 1.5px solid light-dark(#d6e5dc, var(--border)) !important;
  box-shadow: 0 1px 3px rgba(6, 44, 32, 0.03), inset 0 1px 0 light-dark(#ffffff, var(--highlight)) !important;
  cursor: pointer !important;
  user-select: none;
  transition: transform 0.15s cubic-bezier(0.16, 1, 0.3, 1), background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease !important;
}

.barangay-3d-tile:hover {
  transform: translateY(-1px);
  border-color: light-dark(#7dcba3, var(--successBorder)) !important;
  background: light-dark(#f7faf8, var(--hover)) !important;
  box-shadow: 0 3px 8px rgba(6, 44, 32, 0.06) !important;
}

.barangay-3d-tile:active {
  transform: translateY(0);
}

.barangay-3d-tile input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

/* Highly-Visible 3D Checkbox */
.barangay-tile-checkbox {
  width: 22px !important;
  height: 22px !important;
  min-width: 22px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 7px !important;
  border: 2px solid light-dark(#84b69d, var(--border)) !important;
  background: light-dark(#ffffff, var(--surface)) !important;
  box-shadow: inset 0 1.5px 2px rgba(6, 44, 32, 0.08) !important;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  box-sizing: border-box !important;
}

.barangay-tile-checkbox .checkbox-svg-check {
  display: none !important;
}

.barangay-tile-name {
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 650;
  color: light-dark(#1e3a2f, var(--textPrimary));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color 0.15s ease;
}

/* Checked / Selected Tile State */
.barangay-3d-tile.is-selected,
.barangay-3d-tile:has(input:checked) {
  border: 2px solid light-dark(#059669, var(--successBorder)) !important;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#ebf8f1, var(--surfaceAlt)) 100%) !important;
  box-shadow: 0 3px 10px rgba(5, 150, 105, 0.16), inset 0 1px 0 light-dark(#ffffff, var(--highlight)) !important;
}

.barangay-3d-tile.is-selected .barangay-tile-checkbox,
.barangay-3d-tile:has(input:checked) .barangay-tile-checkbox,
.barangay-tile-checkbox.is-checked {
  background: linear-gradient(145deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#047857, var(--brand)) 100%) !important;
  border-color: light-dark(#047857, var(--successBorder)) !important;
  box-shadow: 0 2px 6px rgba(5, 150, 105, 0.4), inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.35), var(--highlight)) !important;
  transform: scale(1.05);
}

.barangay-3d-tile.is-selected .barangay-tile-checkbox .checkbox-svg-check,
.barangay-3d-tile:has(input:checked) .barangay-tile-checkbox .checkbox-svg-check,
.barangay-tile-checkbox.is-checked .checkbox-svg-check {
  display: block !important;
  width: 14px !important;
  height: 14px !important;
  stroke: light-dark(#ffffff, var(--onAccent)) !important;
  stroke-width: 3.5 !important;
}

.barangay-3d-tile.is-selected .barangay-tile-name,
.barangay-3d-tile:has(input:checked) .barangay-tile-name {
  color: light-dark(#046c4e, var(--primaryGreen)) !important;
  font-weight: 800 !important;
}

