/* --------------------------------------------------------------------------
   REQUEST OFFICIAL MODAL (Clean, Direct, 3D Luxury Form)
   -------------------------------------------------------------------------- */
.modal-card.modal-card--official-request {
  width: min(660px, 94vw);
  border-radius: 26px;
  border: 1.5px solid light-dark(rgba(255, 255, 255, 0.6), color-mix(in srgb, var(--border) 60%, transparent));
  background: light-dark(#ffffff, var(--surface));
  box-shadow:
    0 32px 85px rgba(6, 44, 32, 0.28),
    0 8px 24px rgba(0, 0, 0, 0.1),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  overflow: hidden;
  animation: officialModalPopIn 0.26s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes officialModalPopIn {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.modal-card.modal-card--official-request .modal-header {
  padding: 22px 28px 16px;
  background: linear-gradient(135deg, light-dark(#f8fdfa, var(--surface)) 0%, light-dark(#edf7f2, var(--surfaceAlt)) 100%);
  border-bottom: 1.5px solid light-dark(#dcece3, var(--border));
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-card.modal-card--official-request #modalEyebrow {
  display: inline-flex !important;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
  padding: 3px 10px;
  border-radius: 9999px;
  background: linear-gradient(135deg, light-dark(#ecfdf5, var(--successSurface)) 0%, light-dark(#d1fae5, var(--successSurface)) 100%);
  border: 1px solid light-dark(#a7f3d0, var(--successBorder));
  color: light-dark(#065f46, var(--primaryGreen));
  font-family: 'Outfit', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  box-shadow: 0 1px 3px rgba(16, 185, 129, 0.12);
}

.modal-card.modal-card--official-request #modalTitle {
  font-family: 'Outfit', sans-serif;
  font-size: 22px;
  font-weight: 850;
  color: light-dark(#0c291e, var(--textPrimary));
  letter-spacing: -0.02em;
  margin: 0;
}

.modal-card.modal-card--official-request #modalClose {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d2e4dc, var(--border));
  color: light-dark(#4b6b5d, var(--textSecondary));
  box-shadow: 0 2px 6px rgba(6, 44, 32, 0.06);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  display: grid;
  place-items: center;
}

.modal-card.modal-card--official-request #modalClose:hover {
  background: light-dark(#fee2e2, var(--errorSurface));
  border-color: light-dark(#fca5a5, var(--errorBorder));
  color: light-dark(#b91c1c, var(--error));
  transform: rotate(90deg) scale(1.08);
}

/* Modal Body */
.modal-card.modal-card--official-request .modal-body {
  padding: 24px 28px;
  background: light-dark(#fbfdfc, var(--surface));
  overflow-y: visible;
}

.official-req-container {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.official-req-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px 20px;
}

.official-req-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.official-req-field label {
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 750;
  color: light-dark(#1a3c30, var(--textPrimary));
  letter-spacing: -0.01em;
}

.req-star {
  color: light-dark(#b52d38, var(--error));
  font-weight: 800;
}

/* 3D Tactile Input Capsule */
.official-req-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 46px;
  border-radius: 14px;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d4e3db, var(--border));
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, 0.03),
    0 2px 6px rgba(6, 44, 32, 0.04);
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.official-req-input-wrap:focus-within {
  border-color: light-dark(#10b981, var(--successBorder));
  box-shadow:
    0 0 0 3.5px rgba(16, 185, 129, 0.2),
    inset 0 1px 2px rgba(0, 0, 0, 0.02);
  transform: translateY(-1px);
}

.req-field-icon {
  position: absolute;
  left: 12px;
  font-size: 20px;
  color: light-dark(#087454, var(--primaryGreen));
  pointer-events: none;
  transition: transform 0.2s ease, color 0.2s ease;
}

.official-req-input-wrap:focus-within .req-field-icon {
  color: light-dark(#047857, var(--primaryGreen));
  transform: scale(1.1);
}

.official-req-input-wrap input,
.official-req-input-wrap select {
  width: 100%;
  height: 46px;
  padding: 0 14px 0 42px;
  border: none;
  background: transparent;
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  color: light-dark(#0f241d, var(--textPrimary));
  outline: none;
  border-radius: 14px;
}

.official-req-input-wrap input::placeholder {
  color: light-dark(#8fa298, var(--textSecondary));
  font-weight: 500;
}

.official-req-input-wrap select {
  appearance: none;
  cursor: pointer;
  padding-right: 38px;
}

.req-dropdown-arrow {
  position: absolute;
  right: 12px;
  font-size: 20px;
  color: light-dark(#64748b, var(--textSecondary));
  pointer-events: none;
  transition: transform 0.2s ease;
}

.official-req-input-wrap:focus-within .req-dropdown-arrow {
  color: light-dark(#087f60, var(--primaryGreen));
}

/* Eye Password Toggle Button */
.req-eye-btn {
  position: absolute;
  right: 8px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: none;
  background: transparent;
  border-radius: 8px;
  color: light-dark(#64748b, var(--textSecondary));
  cursor: pointer;
  transition: all 0.18s ease;
}

.req-eye-btn:hover {
  background: light-dark(#f1f5f9, var(--hover));
  color: light-dark(#0f241d, var(--textPrimary));
}

.req-eye-btn .material-symbols-rounded {
  font-size: 19px;
}

/* Single Direct 3D Notice Strip */
.official-req-notice {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 14px;
  background: linear-gradient(135deg, light-dark(#f0fdf4, var(--surfaceAlt)) 0%, light-dark(#dcfce7, var(--successSurface)) 100%);
  border: 1px solid light-dark(#bbf7d0, var(--successBorder));
  box-shadow: inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.notice-icon-circle {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 100%);
  color: light-dark(#ffffff, var(--onAccent));
  box-shadow: 0 2px 6px rgba(16, 185, 129, 0.35);
}

.notice-icon-circle .material-symbols-rounded {
  font-size: 18px;
}

.official-req-notice p {
  margin: 0;
  font-family: 'Outfit', sans-serif;
  font-size: 12.5px;
  font-weight: 600;
  color: light-dark(#166534, var(--primaryGreen));
  line-height: 1.4;
}

/* Modal Actions Footer */
.modal-card.modal-card--official-request .modal-actions {
  padding: 16px 28px 20px;
  background: light-dark(#ffffff, var(--surface));
  border-top: 1.5px solid light-dark(#e6efea, var(--border));
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
}

.req-cancel-btn {
  min-height: 44px;
  padding: 0 20px;
  border-radius: 12px;
  border: 1.5px solid light-dark(#d4e3db, var(--border));
  background: light-dark(#ffffff, var(--surface));
  color: light-dark(#4b6b5d, var(--textSecondary));
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 750;
  cursor: pointer;
  transition: all 0.2s ease;
}

.req-cancel-btn:hover {
  background: light-dark(#f1f5f9, var(--hover));
  color: light-dark(#1e293b, var(--textPrimary));
  border-color: light-dark(#cbd5e1, var(--border));
}

.req-submit-btn {
  min-height: 44px;
  padding: 0 24px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 60%, light-dark(#047857, var(--brand)) 100%);
  border: 1px solid light-dark(rgba(110, 231, 183, 0.5), color-mix(in srgb, var(--successBorder) 50%, transparent));
  border-top: 1.5px solid light-dark(rgba(255, 255, 255, 0.7), color-mix(in srgb, var(--border) 70%, transparent));
  color: light-dark(#ffffff, var(--onAccent));
  font-family: 'Outfit', sans-serif;
  font-size: 14px;
  font-weight: 800;
  box-shadow:
    0 8px 20px rgba(5, 150, 105, 0.4),
    0 2px 6px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.4), var(--highlight));
  cursor: pointer;
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.req-submit-btn:hover {
  transform: translateY(-1.5px);
  box-shadow:
    0 12px 26px rgba(5, 150, 105, 0.5),
    0 4px 8px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.5), var(--highlight));
}

.req-submit-btn:active {
  transform: translateY(0);
}

.req-submit-btn .material-symbols-rounded {
  font-size: 19px;
  transition: transform 0.2s ease;
}

.req-submit-btn:hover .material-symbols-rounded {
  transform: translateX(2px);
}

@media (max-width: 640px) {
  .official-req-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .modal-card.modal-card--official-request .modal-header,
  .modal-card.modal-card--official-request .modal-body,
  .modal-card.modal-card--official-request .modal-actions {
    padding-inline: 18px;
  }
}

