  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  transition: all 0.2s ease;
}

.sleek-control-capsule:hover {
  border-color: transparent !important;
  box-shadow: none !important;
}

.sleek-control-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 2px 6px;
  transition: opacity 0.2s ease;
}

.sleek-control-item label {
  font-family: 'Outfit', sans-serif;
  font-size: 10px;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: light-dark(#065f46, var(--primaryGreen));
  margin: 0;
  white-space: nowrap;
}

.sleek-select {
  border: none;
  background: transparent;
  color: light-dark(#0d3d2e, var(--textPrimary));
  font-family: 'Outfit', 'Manrope', sans-serif;
