  transition: color 0.18s ease;
}

.sleek-select:hover,
.sleek-select:focus-visible {
  color: light-dark(#087454, var(--primaryGreen));
}

.sleek-control-divider {
  width: 1px;
  height: 16px;
  background: light-dark(rgba(195, 222, 211, 0.85), color-mix(in srgb, var(--surfaceAlt) 85%, transparent));
  margin: 0 4px;
}

/* 3D Floating Category Tabs */
.barili-analytics-tabs {
  display: flex;
  gap: 8px;
  padding: 6px;
  background: linear-gradient(180deg, light-dark(#edf5f0, var(--surfaceAlt)) 0%, light-dark(#e3eee7, var(--surfaceAlt)) 100%);
  border: 1px solid light-dark(rgba(205, 226, 217, 0.95), color-mix(in srgb, var(--border) 95%, transparent));
  border-radius: 18px;
  box-shadow: inset 0 2px 5px rgba(7, 56, 42, 0.06), inset 0 1px 2px rgba(0, 0, 0, 0.03);
}

.barili-analytics-tabs button {
