  border-radius: 13px;
  background: transparent;
  color: light-dark(#486355, var(--textSecondary));
  font: 750 13px 'Outfit', 'Manrope', sans-serif;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.barili-analytics-tabs button .material-symbols-rounded {
  font-size: 18px;
  transition: transform 0.22s cubic-bezier(0.16, 1, 0.3, 1), color 0.22s ease;
}

.barili-analytics-tabs button:hover {
  color: light-dark(#065f46, var(--primaryGreen));
