/* ==========================================================================
   Account Dossier / User Details 3D Modal ("3 Dots Action Page")
   ========================================================================== */

.modal-card--user-detail {
  width: min(760px, 95vw);
  max-height: calc(100vh - 40px);
  border-radius: 24px;
  border: 1.5px solid light-dark(#cfe2d8, var(--border));
  box-shadow:
    0 30px 80px -10px rgba(5, 45, 33, 0.3),
    0 12px 32px -4px rgba(5, 45, 33, 0.12),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.9), var(--highlight));
  overflow: hidden;
  animation: modalScalePop 0.24s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes modalScalePop {
  from { opacity: 0; transform: scale(0.95) translateY(10px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.modal-card--user-detail .modal-header {
  padding: 20px 26px;
  background: linear-gradient(180deg, light-dark(#f8fbf9, var(--surface)) 0%, light-dark(#edf7f2, var(--surfaceAlt)) 100%);
  border-bottom: 1.5px solid light-dark(#d8e8e0, var(--border));
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-card--user-detail .modal-header::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087454, var(--brand)) 50%, light-dark(#044b36, var(--brandStrong)) 100%);
}

.modal-card--user-detail .modal-header h2 {
  margin: 0;
  font-family: 'Outfit', sans-serif;
  font-size: 20px;
  font-weight: 800;
  color: light-dark(#0c2b20, var(--textPrimary));
  letter-spacing: -0.01em;
}

.modal-card--user-detail #modalClose {
  width: 38px;
  height: 38px;
  min-width: 38px;
  border-radius: 50%;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d2e4dc, var(--border));
  color: light-dark(#4b6b5d, var(--textSecondary));
  box-shadow: 0 2px 6px rgba(6, 44, 32, 0.06);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  display: grid;
  place-items: center;
  cursor: pointer;
}

.modal-card--user-detail #modalClose:hover {
  background: light-dark(#fee2e2, var(--errorSurface));
  border-color: light-dark(#fca5a5, var(--errorBorder));
  color: light-dark(#b91c1c, var(--error));
  transform: rotate(90deg) scale(1.08);
}

.modal-card--user-detail .modal-body {
  padding: 24px 26px;
  background: light-dark(#fbfdfc, var(--surface));
  overflow-y: auto;
  overflow-x: hidden;
  max-height: calc(100vh - 190px);
}

.modal-card--user-detail .modal-actions {
  padding: 16px 26px;
  background: light-dark(#ffffff, var(--surface));
  border-top: 1.5px solid light-dark(#dce8e1, var(--border));
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
}

/* User Detail 3D Hero */
.user-detail-hero-3d {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 20px 24px;
  border-radius: 20px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f0fdf4, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#c2e2d4, var(--successBorder));
  box-shadow:
    0 8px 24px rgba(6, 44, 32, 0.05),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  margin-bottom: 20px;
  position: relative;
  overflow: hidden;
}

.user-detail-hero-3d::after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 160px;
  height: 100%;
  background: radial-gradient(circle at top right, light-dark(rgba(16, 185, 129, 0.12), color-mix(in srgb, var(--brand) 12%, transparent)), transparent 70%);
  pointer-events: none;
}

.user-detail-hero-3d__avatar-wrap .people-avatar--large {
  width: 66px;
  min-width: 66px;
  height: 66px;
  border-radius: 20px;
  font-size: 24px;
  font-weight: 850;
  box-shadow:
    0 8px 24px rgba(8, 87, 63, 0.18),
    inset 0 2px 1px light-dark(rgba(255, 255, 255, 0.7), var(--highlight));
}

.user-detail-hero-3d__content {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 6px;
}

.user-detail-hero-3d__badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.user-detail-hero-3d__name {
  margin: 0;
  font-family: 'Outfit', sans-serif;
  font-size: 22px;
  font-weight: 850;
  color: light-dark(#064e3b, var(--primaryGreen));
  letter-spacing: -0.01em;
  line-height: 1.25;
}

.user-detail-hero-3d__position {
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: light-dark(#047857, var(--primaryGreen));
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 700;
}

.user-detail-hero-3d__position .material-symbols-rounded {
  font-size: 17px;
  color: light-dark(#087454, var(--primaryGreen));
}

/* User Detail 3D Grid */
.user-detail-3d-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 22px;
  width: 100%;
}

.user-detail-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  border-radius: 16px;
  background: light-dark(#ffffff, var(--surface));
  border: 1.5px solid light-dark(#d9eae1, var(--border));
  box-shadow:
    0 2px 8px rgba(6, 44, 32, 0.03),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  transition: transform 0.18s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.18s ease,
              border-color 0.18s ease;
  min-width: 0;
}

.user-detail-card:hover {
  transform: translateY(-1px);
  border-color: light-dark(#10b981, var(--successBorder));
  box-shadow:
    0 6px 16px rgba(6, 44, 32, 0.07),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.user-detail-card--full {
  grid-column: 1 / -1;
}

.user-detail-card__icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: 12px;
  background: linear-gradient(145deg, light-dark(#ecfdf5, var(--successSurface)) 0%, light-dark(#d1fae5, var(--successSurface)) 100%);
  border: 1.5px solid light-dark(#a7f3d0, var(--successBorder));
  color: light-dark(#047857, var(--primaryGreen));
  font-size: 20px;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(16, 185, 129, 0.12), inset 0 1px 0 light-dark(#ffffff, var(--highlight));
}

.user-detail-card__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  flex: 1;
}

.user-detail-card__body small {
  font-family: 'Outfit', sans-serif;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: light-dark(#628276, var(--textSecondary));
}

.user-detail-card__body strong {
  font-family: 'Outfit', sans-serif;
  font-size: 14.5px;
  font-weight: 750;
  color: light-dark(#0f241d, var(--textPrimary));
  overflow-wrap: anywhere;
  word-break: break-word;
  line-height: 1.35;
}

.user-detail-card__note {
  font-size: 11.5px;
  color: light-dark(#728c82, var(--textSecondary));
  margin-top: 1px;
}

@media (max-width: 600px) {
  .user-detail-3d-grid {
    grid-template-columns: 1fr;
  }
  .user-detail-card--full {
    grid-column: 1;
  }
  .user-detail-hero-3d {
    flex-direction: column;
    align-items: flex-start;
    padding: 18px;
  }
}

/* User Status Management Card (For Admins) */
.user-status-management-card {
  padding: 18px 20px;
  border-radius: 18px;
  background: linear-gradient(145deg, light-dark(#ffffff, var(--surface)) 0%, light-dark(#f7fbf9, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#cfe3da, var(--border));
  box-shadow:
    0 4px 16px rgba(6, 44, 32, 0.05),
    inset 0 1px 0 light-dark(#ffffff, var(--highlight));
  display: grid;
  gap: 14px;
}

.user-status-management-card__header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid light-dark(#e4eee9, var(--border));
}

.user-status-management-card__header .material-symbols-rounded {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: light-dark(#ebf7f1, var(--surfaceAlt));
  color: light-dark(#087454, var(--primaryGreen));
  font-size: 20px;
  border: 1px solid light-dark(#c2e2d4, var(--successBorder));
  flex-shrink: 0;
}

.user-status-management-card__header strong {
  font-family: 'Outfit', sans-serif;
  font-size: 14.5px;
  font-weight: 800;
  color: light-dark(#0b3424, var(--textPrimary));
  display: block;
}

.user-status-management-card__header small {
  font-size: 12px;
  color: light-dark(#668278, var(--textSecondary));
}

.user-status-management-card__fields {
  display: grid;
  gap: 12px;
}

.user-status-management-card__fields .field {
  display: grid;
  gap: 6px;
}

.user-status-management-card__fields .field span {
  font-family: 'Outfit', sans-serif;
  font-size: 11.5px;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: light-dark(#275243, var(--textPrimary));
}

.user-status-management-card__fields select,
.user-status-management-card__fields textarea {
  width: 100%;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1.5px solid light-dark(#cedfd7, var(--border));
  background: light-dark(#ffffff, var(--surface));
  font-family: 'Manrope', sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  color: light-dark(#12372c, var(--textPrimary));
  outline: 0;
  box-shadow: inset 0 1.5px 3px rgba(6, 44, 32, 0.04);
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.user-status-management-card__fields select:focus,
.user-status-management-card__fields textarea:focus {
  border-color: light-dark(#087454, var(--successBorder));
  box-shadow: 0 0 0 3px rgba(8, 116, 84, 0.14), inset 0 1px 2px rgba(6, 44, 32, 0.04);
}

/* Modal 3D Buttons */
.button--3d-primary {
  min-height: 44px;
  padding: 0 20px;
  border-radius: 12px;
  background: linear-gradient(135deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087454, var(--brand)) 100%) !important;
  border: 1px solid light-dark(#065f46, var(--successBorder)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  font-family: 'Outfit', sans-serif;
  font-size: 13.5px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow:
    0 4px 14px rgba(8, 116, 84, 0.35),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.3), var(--highlight));
  transition: transform 0.18s cubic-bezier(0.16, 1, 0.3, 1),
              box-shadow 0.18s ease;
}

.button--3d-primary:hover {
  transform: translateY(-1px);
  box-shadow:
    0 6px 20px rgba(8, 116, 84, 0.45),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.35), var(--highlight));
}

.button--3d-primary:active {
  transform: translateY(0);
}

.button--resend-3d {
  min-height: 44px;
  padding: 0 18px;
  border-radius: 12px;
  border: 1.5px solid light-dark(#bad5fb, var(--infoBorder));
  background: light-dark(#f0f7ff, var(--surfaceAlt));
  color: light-dark(#1967d2, var(--info));
  font-family: 'Outfit', sans-serif;
  font-size: 13px;
  font-weight: 750;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: transform 0.18s ease, background 0.18s ease;
}

.button--resend-3d:hover {
  background: light-dark(#e1effe, var(--infoSurface));
  transform: translateY(-1px);
}

@media (max-width: 640px) {
  .user-detail-hero-3d {
    flex-direction: column;
    text-align: center;
    gap: 14px;
  }
  .user-detail-hero-3d__badges {
    justify-content: center;
  }
  .user-detail-hero-3d__position {
    justify-content: center;
  }
  .user-detail-3d-grid {
    grid-template-columns: 1fr;
  }
  .user-detail-card--full {
    grid-column: auto;
  }
}
/* Managed LGU department directory */
.structure-tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 20px; padding: 6px; width: fit-content; max-width: 100%; border: 1px solid light-dark(#d8e8e0, var(--border)); border-radius: 16px; background: light-dark(#edf6f1, var(--surfaceAlt)); }
.structure-tab { border: 0; border-radius: 11px; padding: 11px 18px; background: transparent; color: light-dark(#35594d, var(--textSecondary)); font: 700 14px 'Manrope', sans-serif; cursor: pointer; }
.structure-tab.is-active { background: light-dark(#087458, var(--brand)); color: light-dark(#fff, var(--onAccent)); box-shadow: 0 4px 12px rgba(7, 80, 59, .16); }
.structure-tab:focus-visible { outline: 3px solid light-dark(#2cad87, var(--successBorder)); outline-offset: 2px; }
.department-management { margin-bottom: 24px; padding: 24px; }
.department-management__header { align-items: flex-start; gap: 20px; }
.department-management__header p { margin: 6px 0 0; color: var(--muted, light-dark(#64776f, var(--textSecondary))); }
.department-management__list { display: grid; gap: 12px; margin-top: 20px; }
.department-management__item { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 16px; padding: 16px 18px; border: 1px solid light-dark(#d8e8e0, var(--border)); border-radius: 16px; background: light-dark(#f9fcfa, var(--surface)); }
.department-management__item strong,
.department-management__item small { display: block; }
.department-management__item small { margin-top: 4px; color: light-dark(#61776e, var(--textSecondary)); }
.department-management__actions { display: flex; align-items: center; justify-content: flex-end; flex-wrap: wrap; gap: 8px; }
.table-action--danger { color: light-dark(#a52727, var(--error)); }
@media (max-width: 760px) {
  .topbar .admin-chip { flex: 0 0 50px; }
}
@media (max-width: 720px) {
  .department-management { padding: 18px; }
  .department-management__header { align-items: stretch; flex-direction: column; }
  .department-management__item { grid-template-columns: 1fr auto; }
  .department-management__actions { grid-column: 1 / -1; }
}

/* Close controls must remain visible on every light modal/header variant. */
button[aria-label^="Close" i] {
  border-color: light-dark(#b91c1c, var(--errorBorder)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  background: linear-gradient(145deg, light-dark(#c93636, var(--errorSolid)) 0%, light-dark(#c93636, var(--errorSolid)) 100%) !important;
  box-shadow:
    0 7px 16px rgba(185, 28, 28, 0.28),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.3), var(--highlight)) !important;
}

button[aria-label^="Close" i]:hover {
  border-color: light-dark(#991b1b, var(--errorBorder)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  background: linear-gradient(145deg, light-dark(#c93636, var(--errorHover)) 0%, light-dark(#b91c1c, var(--errorHover)) 100%) !important;
  box-shadow:
    0 9px 20px rgba(153, 27, 27, 0.34),
    inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.28), var(--highlight)) !important;
}

button[aria-label^="Close" i] .material-symbols-rounded {
  color: inherit !important;
}

.concern-map-scope-badge {
