  border-radius: 999px;
  color: light-dark(#78350f, var(--warning));
  background: light-dark(rgba(255, 251, 235, 0.95), color-mix(in srgb, var(--warningSurface) 95%, transparent));
  box-shadow: 0 8px 22px rgba(120, 53, 15, 0.18);
