/* DOM-rendered copy of the mobile app's barangay polygons. It stays visible
   even on browsers that fail to composite the WebGL map canvas. */
.concern-map-boundary-overlay {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.concern-map-boundary-shape {
  paint-order: stroke fill;
  transition: filter 0.14s ease, fill-opacity 0.14s ease, stroke-width 0.14s ease;
}

.concern-map-boundary-shape.is-hovered {
  stroke: light-dark(#022c22, var(--textPrimary)) !important;
  stroke-width: 3.2px !important;
  fill-opacity: 0.9 !important;
  filter: drop-shadow(0 4px 4px rgba(2, 44, 34, 0.28));
}

.concern-map-boundary-shape.is-assigned {
  transform: translateY(-6px);
  transform-box: fill-box;
  transform-origin: center;
  filter:
    drop-shadow(0 5px 0 rgba(180, 83, 9, 0.45))
    drop-shadow(0 13px 8px rgba(120, 53, 15, 0.3));
}

