.organization-registration-layout {
  position: relative;
  min-height: 100vh;
  min-height: 100dvh;
  padding: clamp(20px, 4vw, 56px);
  place-items: center;
  background:
    radial-gradient(ellipse 85% 65% at 12% 14%, light-dark(rgba(16, 185, 129, 0.28), color-mix(in srgb, var(--brand) 28%, transparent)) 0%, transparent 60%),
    radial-gradient(ellipse 75% 55% at 88% 86%, light-dark(rgba(245, 158, 11, 0.14), color-mix(in srgb, var(--warningSolid) 14%, transparent)) 0%, transparent 55%),
    radial-gradient(circle at 50% 45%, light-dark(rgba(6, 78, 59, 0.45), color-mix(in srgb, var(--brandStrong) 45%, transparent)) 0%, transparent 65%),
    linear-gradient(142deg, light-dark(#022319, var(--brandStrong)) 0%, light-dark(#064e3b, var(--brandStrong)) 45%, light-dark(#032b1f, var(--brandStrong)) 100%);
  font-family: 'Manrope', sans-serif;
  overflow-x: hidden;
  isolation: isolate;
}

.organization-registration-layout::before {
  content: "";
  position: absolute;
  top: -18%;
  left: -12%;
  width: min(65vw, 700px);
  height: min(65vw, 700px);
  border-radius: 50%;
  background: radial-gradient(circle, light-dark(rgba(52, 211, 153, 0.15), color-mix(in srgb, var(--brand) 15%, transparent)) 0%, transparent 70%);
  filter: blur(55px);
  pointer-events: none;
  z-index: 0;
}

.organization-registration-layout::after {
  content: "";
  position: absolute;
  bottom: -22%;
  right: -10%;
  width: min(60vw, 650px);
  height: min(60vw, 650px);
  border-radius: 50%;
  background: radial-gradient(circle, light-dark(rgba(16, 185, 129, 0.18), color-mix(in srgb, var(--brand) 18%, transparent)) 0%, transparent 70%);
  filter: blur(60px);
  pointer-events: none;
  z-index: 0;
}

.organization-registration-layout:not([hidden]) {
  display: grid;
}

.organization-registration-layout[hidden],
.activation-layout[hidden] {
  display: none !important;
}

.organization-registration-card {
  position: relative;
  z-index: 1;
  width: min(100%, 820px);
  padding: clamp(24px, 4vw, 44px);
  border: 1px solid light-dark(rgba(255, 255, 255, 0.85), color-mix(in srgb, var(--border) 85%, transparent));
  border-radius: 28px;
  background: light-dark(rgba(255, 255, 255, 0.98), color-mix(in srgb, var(--surface) 98%, transparent));
