}

.organization-registration-heading { display: flex; align-items: center; gap: 16px; margin-bottom: 26px; }
.organization-registration-heading img { width: 62px; height: 62px; object-fit: contain; }
.organization-registration-heading span { color: light-dark(#087454, var(--primaryGreen)); font-size: 11px; font-weight: 850; letter-spacing: .12em; }
