}

.grouped-action-menu-item:disabled .material-symbols-rounded,
.grouped-action-menu-item[disabled] .material-symbols-rounded {
  opacity: 0.4;
}

.grouped-action-menu-item .action-dot {
  width: 8px;
  height: 8px;
