}

.action-dot.dot-in-progress { background: light-dark(#0284c7, var(--infoSolid)); box-shadow: 0 0 0 2px rgba(2, 132, 199, 0.2); }
.action-dot.dot-needs-attention { background: light-dark(#d97706, var(--warningSolid)); box-shadow: 0 0 0 2px rgba(217, 119, 6, 0.2); }
