/* Screen Styling for Summons Document (Official KP Form No. 9 - 2 Pages) */
.summons-bondpaper-container {
  display: flex;
  flex-direction: column;
  gap: 36px;
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  padding: 10px 0 36px;
  box-sizing: border-box;
}

.summons-sheet-paper {
  position: relative;
  background: light-dark(#ffffff, var(--surface));
  color: light-dark(#000000, var(--textPrimary));
  padding: 48px 56px 44px;
  border-radius: 2px;
  border: 1px solid light-dark(#d1d5db, var(--border));
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.12);
  font-family: 'Times New Roman', Times, Georgia, serif;
  line-height: 1.5;
  box-sizing: border-box;
  width: 100%;
  min-height: 1040px;
  display: flex;
  flex-direction: column;
}

.summons-page-indicator {
  position: absolute;
  top: -24px;
  left: 2px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: light-dark(#64748b, var(--textSecondary));
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Official Header */
.kp-official-header {
  position: relative;
  padding: 0 64px;
  text-align: center;
  margin-top: 4px;
  line-height: 1.35;
}

.kp-header-seal {
  position: absolute;
  top: 0;
  width: 56px;
  height: 56px;
  object-fit: contain;
}

.kp-header-seal--municipal { right: 0; }
.kp-header-seal--barangay { left: 0; }

.kp-signatories-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 32px;
  margin-top: 42px;
