}
.complaint-hearing-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  color: light-dark(#0f172a, var(--textPrimary));
}
.complaint-hearing-title .material-symbols-rounded {
  font-size: 20px;
  color: light-dark(#087454, var(--primaryGreen));
}
.complaint-delivery-badge {
  font-size: 12px;
  font-weight: 700;
  color: light-dark(#0284c7, var(--info));
  background: light-dark(#e0f2fe, var(--infoSurface));
