}
.complaint-list { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 8px; }
.complaint-list p { margin: 2px 0 0; color: var(--muted); }
.complaint-ask { display: flex; flex-direction: column; gap: 8px; }
.complaint-ask__label { margin: 0; font-size: 13px; font-weight: 800; color: var(--ink); }
.complaint-ask__hint { margin: 4px 0 0; font-size: 12.5px; color: var(--muted); }
.complaint-check { display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 6px 12px; border: 1.5px solid var(--line); border-radius: 12px; cursor: pointer; }
.complaint-check input { width: 18px; height: 18px; accent-color: light-dark(var(--green-700), var(--primaryGreen)); flex: none; }
.complaint-check em { margin-left: auto; padding: 2px 8px; border-radius: 6px; background: light-dark(#fff4dc, var(--warningSurface)); color: light-dark(#7a4b00, var(--warning)); font-size: 11.5px; font-style: normal; font-weight: 800; }
.complaint-check--radio span { display: flex; flex-direction: column; }
.complaint-check--radio small { color: var(--muted); }
.complaint-check:has(input:checked) { border-color: light-dark(var(--green-700), var(--successBorder)); background: var(--green-50); }

/* ==========================================================================
   Barangay Complaints Table Format (Matching Concerns Page Table System)
   ========================================================================== */

.complaint-view-toggle {
  display: inline-flex;
  align-items: center;
  background: light-dark(#f1f5f9, var(--surfaceAlt));
  padding: 3px;
  border-radius: 12px;
  border: 1px solid light-dark(#e2e8f0, var(--infoBorder));
  gap: 2px;
  margin-left: 8px;
}

.complaint-view-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 13px;
  border-radius: 9px;
  border: none;
  background: transparent;
  color: light-dark(#64748b, var(--textSecondary));
  font-family: 'Manrope', sans-serif;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  line-height: 1;
}

.complaint-view-toggle-btn .material-symbols-rounded {
  font-size: 16px;
}

.complaint-view-toggle-btn.is-active {
  background: light-dark(#ffffff, var(--surface));
  color: light-dark(#064e3b, var(--primaryGreen));
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08), 0 2px 8px rgba(6, 78, 59, 0.06);
}

.complaint-view-toggle-btn:hover:not(.is-active) {
  color: light-dark(#0f172a, var(--textPrimary));
  background: light-dark(rgba(255, 255, 255, 0.5), color-mix(in srgb, var(--hover) 50%, transparent));
}

.complaint-board.is-table-view {
  display: block !important;
  width: 100% !important;
}

.complaint-table-wrap {
  position: relative;
  overflow-x: auto;
  border: 1px solid light-dark(rgba(16, 185, 129, 0.22), color-mix(in srgb, var(--successBorder) 22%, transparent));
  border-radius: 18px;
  background: light-dark(#ffffff, var(--surface));
  box-shadow: 0 16px 38px -4px rgba(6, 78, 59, 0.09), 0 4px 12px -2px rgba(6, 78, 59, 0.05), inset 0 1px 0 light-dark(rgba(255, 255, 255, 0.9), var(--highlight));
  isolation: isolate;
  width: 100%;
}

.complaint-table-wrap::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, light-dark(#087f60, var(--brand)) 0%, light-dark(#087f60, var(--brand)) 50%, light-dark(#34d399, var(--brand)) 100%);
