  border-spacing: 0;
  font-size: 13px;
  text-align: left;
}

.complaint-reports-table thead {
  background: linear-gradient(180deg, light-dark(#0a4d3a, var(--brandStrong)) 0%, light-dark(#06392b, var(--brandStrong)) 100%);
