}

.complaint-reports-table thead th {
  background: linear-gradient(180deg, light-dark(#07523f, var(--brandStrong)) 0%, light-dark(#043627, var(--brandStrong)) 100%) !important;
  padding: 14px 16px !important;
  border-bottom: 2px solid light-dark(#022319, var(--successBorder)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  font: 800 11.5px 'Manrope', sans-serif !important;
  letter-spacing: 0.07em !important;
  text-transform: uppercase !important;
  white-space: nowrap !important;
  vertical-align: middle !important;
  position: relative !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45) !important;
}

.complaint-reports-table thead th:first-child {
  border-top-left-radius: 17px !important;
}

.complaint-reports-table thead th:last-child {
  border-top-right-radius: 17px !important;
}

.complaint-reports-table thead th:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 25%;
  height: 50%;
  width: 1px;
  background: light-dark(rgba(255, 255, 255, 0.16), color-mix(in srgb, var(--surface) 16%, transparent)) !important;
}

.complaint-table-sort-btn {
  background: transparent;
  border: none;
  color: inherit;
  font: inherit;
  padding: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  letter-spacing: inherit;
  text-transform: inherit;
}

.complaint-table-sort-btn:hover {
  color: light-dark(#a7f3d0, var(--primaryGreen));
}

.complaint-table-sort-btn .material-symbols-rounded {
  font-size: 15px;
  opacity: 0.85;
}

.complaint-reports-table tbody tr {
  background: light-dark(#ffffff, var(--surface));
  transition: background 0.18s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.18s ease;
  cursor: pointer;
}

.complaint-reports-table tbody tr:nth-child(even) {
