}

.complaint-reports-table tbody tr:hover {
  background: linear-gradient(90deg, light-dark(#f0fdf4, var(--hover)) 0%, light-dark(#f7fdfa, var(--hover)) 100%) !important;
  box-shadow: inset 3px 0 0 #059669;
}

.complaint-reports-table td {
  padding: 13px 16px;
  color: light-dark(#1e293b, var(--textPrimary));
  border-bottom: 1px solid light-dark(#f1f5f9, var(--border));
