/* ==========================================================================
   COMPLAINT WORKFLOW STAGES, STEPPER & ACTION BUTTONS
   ========================================================================== */

.complaint-stage-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.01em;
  white-space: nowrap;
  border: 1px solid transparent;
}
.complaint-stage-pill .material-symbols-rounded {
  font-size: 15px;
}

.stage-filed {
  background: light-dark(#f1f5f9, var(--surfaceAlt));
  color: light-dark(#475569, var(--textSecondary));
  border-color: light-dark(#cbd5e1, var(--border));
}
.stage-review {
  background: light-dark(#fef3c7, var(--warningSurface));
  color: light-dark(#92400e, var(--warning));
  border-color: light-dark(#fde68a, var(--warningBorder));
}
.stage-summons {
  background: light-dark(#f5f3ff, var(--surfaceAlt));
  color: light-dark(#6d28d9, var(--purple));
  border-color: light-dark(#ddd6fe, var(--infoBorder));
}
.stage-hearing {
  background: light-dark(#eff6ff, var(--infoSurface));
  color: light-dark(#1d4ed8, var(--info));
  border-color: light-dark(#bfdbfe, var(--infoBorder));
}
.stage-next-hearing {
  background: light-dark(#fff7ed, var(--warningSurface));
  color: light-dark(#c2410c, var(--error));
  border-color: light-dark(#ffedd5, var(--warningBorder));
}
.stage-mediation {
  background: light-dark(#fdf4ff, var(--surfaceAlt));
  color: light-dark(#a21caf, var(--purple));
  border-color: light-dark(#f5d0fe, var(--purpleBorder));
}
.stage-conciliation {
  background: light-dark(#fef2f2, var(--surfaceAlt));
  color: light-dark(#b91c1c, var(--error));
  border-color: light-dark(#fecaca, var(--errorBorder));
}
.stage-settled {
  background: light-dark(#ecfdf5, var(--successSurface));
  color: light-dark(#047857, var(--primaryGreen));
  border-color: light-dark(#a7f3d0, var(--successBorder));
}
.stage-unsettled {
  background: light-dark(#fef2f2, var(--surfaceAlt));
  color: light-dark(#b52d38, var(--error));
  border-color: light-dark(#fca5a5, var(--errorBorder));
}
.stage-closed {
  background: light-dark(#f8fafc, var(--surface));
  color: light-dark(#334155, var(--textPrimary));
  border-color: light-dark(#e2e8f0, var(--infoBorder));
}

/* Modal Stepper Progression */
.complaint-stepper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  padding: 14px 18px;
  margin-bottom: 20px;
  background: light-dark(#f8fafc, var(--surface));
  border: 1px solid light-dark(#e2e8f0, var(--infoBorder));
  border-radius: 14px;
  overflow-x: auto;
}
.complaint-step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 5px;
  min-width: 68px;
  position: relative;
  opacity: 0.55;
  transition: all 0.2s ease;
}
.complaint-step-item.is-active {
  opacity: 1;
}
.complaint-step-item.is-completed {
  opacity: 0.9;
}
.complaint-step-circle {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: light-dark(#e2e8f0, var(--surfaceAlt));
  color: light-dark(#64748b, var(--textSecondary));
  font-size: 13px;
  font-weight: 700;
  border: 2px solid light-dark(#cbd5e1, var(--border));
}
.complaint-step-item.is-completed .complaint-step-circle {
  background: light-dark(#087f60, var(--brand));
  color: light-dark(#ffffff, var(--onAccent));
  border-color: light-dark(#059669, var(--successBorder));
}
.complaint-step-item.is-active .complaint-step-circle {
  background: light-dark(#0b4a38, var(--brandStrong));
  color: light-dark(#ffffff, var(--onAccent));
  border-color: light-dark(#047857, var(--successBorder));
  box-shadow: 0 0 0 3px rgba(11, 74, 56, 0.2);
}
.complaint-step-label {
  font-size: 11px;
  font-weight: 700;
  color: light-dark(#475569, var(--textSecondary));
  line-height: 1.2;
}
.complaint-step-item.is-active .complaint-step-label {
  color: light-dark(#0b4a38, var(--textPrimary));
}
.complaint-step-divider {
  flex: 1;
  height: 2px;
  background: light-dark(#e2e8f0, var(--surfaceAlt));
  margin: 0 2px 18px 2px;
  min-width: 14px;
}
.complaint-step-divider.is-completed {
  background: light-dark(#087f60, var(--brand));
}

/* Specific Action Buttons */
.button.complaint-btn-settle {
  background: light-dark(#087f60, var(--brand)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  border-color: light-dark(#047857, var(--successBorder)) !important;
}
.button.complaint-btn-settle:hover {
  background: light-dark(#047857, var(--brandHover)) !important;
}

.button.complaint-btn-not-settled {
  background: light-dark(#f97316, var(--warningSolid)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  border-color: light-dark(#ea580c, var(--warningBorder)) !important;
}
.button.complaint-btn-not-settled:hover {
  background: light-dark(#ea580c, var(--warningHover)) !important;
}

.button.complaint-btn-unsettled {
  background: light-dark(#c93636, var(--errorSolid)) !important;
  color: light-dark(#ffffff, var(--onAccent)) !important;
  border-color: light-dark(#b91c1c, var(--errorBorder)) !important;
}
.button.complaint-btn-unsettled:hover {
  background: light-dark(#b91c1c, var(--errorHover)) !important;
}

/* Case Detail Sections */
.complaint-section-box {
  background: light-dark(#ffffff, var(--surface));
  border: 1px solid light-dark(#e2e8f0, var(--infoBorder));
  border-radius: 12px;
  padding: 16px;
  margin-top: 16px;
}
