}

/* Timeline */
.complaint-timeline {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
}
.complaint-timeline-item {
  display: flex;
  gap: 12px;
  position: relative;
  padding-left: 24px;
}
.complaint-timeline-item::before {
  content: "";
  position: absolute;
  left: 6px;
  top: 8px;
  bottom: -16px;
  width: 2px;
  background: light-dark(#e2e8f0, var(--surfaceAlt));
}
.complaint-timeline-item:last-child::before {
  display: none;
}
.complaint-timeline-bullet {
  position: absolute;
  left: 0;
  top: 4px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: light-dark(#0b4a38, var(--brandStrong));
  border: 2px solid light-dark(#ffffff, var(--border));
  box-shadow: 0 0 0 2px #cbd5e1;
}
.complaint-timeline-content {
  flex: 1;
}
.complaint-timeline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2px;
}
.complaint-timeline-status {
  font-size: 13px;
  font-weight: 700;
  color: light-dark(#0f172a, var(--textPrimary));
}
.complaint-timeline-date {
  font-size: 11.5px;
  color: light-dark(#64748b, var(--textSecondary));
}
.complaint-timeline-actor {
  font-size: 12px;
  color: light-dark(#047857, var(--primaryGreen));
  font-weight: 600;
  margin-bottom: 3px;
}
.complaint-timeline-remarks {
  font-size: 12.5px;
  color: light-dark(#334155, var(--textPrimary));
  background: light-dark(#f8fafc, var(--surface));
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid light-dark(#f1f5f9, var(--border));
  margin-top: 4px;
}

