/* ==========================================================================
   Admin View-Only Concern Oversight Registry Styling
   ========================================================================== */
.action-card--admin-oversight {
  background: linear-gradient(135deg, light-dark(#f8fafc, var(--surface)) 0%, light-dark(#f1f5f9, var(--surfaceAlt)) 100%);
  border: 1.5px solid light-dark(#cbd5e1, var(--border));
  border-left: 5px solid light-dark(#0284c7, var(--infoBorder));
