  align-items: flex-start;
  gap: 14px;
}

.action-card--admin-oversight .action-card__info > .material-symbols-rounded {
  font-size: 28px;
  color: light-dark(#0284c7, var(--info));
  background: light-dark(#e0f2fe, var(--infoSurface));
